window.__LEX={"G4700":"<h1>spodos</h1>\n<p>Strong n° 4700 <i>Prononciation [spod-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cendres : placées sur un vêtement fait d'un sac en signe de malheur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σποδός, οῦ (ἡ) :<br>   I</b> cendre, OD. <i>9, 375 ;</i> HH. <i>Merc. 238 ;</i> HDT. <i>2, 140, etc. ; particul. :</i><br><b>      1</b> cendre des morts, ESCHL. <i>Ag. 435, 443, Ch. 687 ;</i> SOPH. <i>El. 758, 1122, 1158, 1198 ;</i> EUR. <i>Suppl. 1130, 1160 ;</i> ANTH. <i>App. 97 ;</i><br><b>      2</b> cendre d’un sacrifice, HDT. <i>4, 35 ;</i> SOPH. <i>O.R. 21 ;</i><br><b>      3</b> cendre dont on se couvre en signe de deuil, EUR. <i>Suppl. 826, etc. ;</i><br><b>      4</b> cendre <i>ou</i> lave de volcan, STR. <i>6, 2, 8, Kram. ;</i><br><b>   II</b> poussière, HDT. <i>4, 172 ;</i><br><b>   III</b> scorie de métaux, HPC. <i>877</i> c, <i>etc</i>. μετρεῖν τὴν σποδόν, ARR. <i>Epict. 3, 26, 17,</i> mesurer la poussière, <i>càd</i>. travailler en pure perte ;<br><b>   IV</b> σποδὸς κυλίκων, πίθων, ANTH. <i>6, 291 ; 7, 455,</i> qui met à sec les verres, les tonneaux, <i>en parl. d’une vieille ivrognesse</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σποδος - σποδός</font>\n<br><br>de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4701":"<h1>spora</h1>\n<p>Strong n° 4701 <i>Prononciation [spor-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>semence</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπορά, ᾶς (ἡ) :<br>      1</b> ensemencement, <i>fig. en parl. d’éducation, de science,</i> PLAT. <i>Riv. 134</i> e ; <i>p. anal</i>. procréation, PLAT. <i>Leg. 729</i> c, <i>783</i> a ; <i>d’où</i> naissance, origine, ESCHL. <i>Pr. 871 ;</i> SOPH. <i>Aj. 1298 ;</i><br><b>      2</b> temps des semailles, EUR. <i>El. 1153 ;</i> TH. <i>H.P. 8, 2, 6 ;</i><br><b>      3</b> semence répandue, EUR. <i>Andr. 637 ; fig</i>. semence, rejeton, SOPH. <i>Tr. 316, 420 ; Ant. 1125, etc. ; d’où</i> postérité, race, génération, EUR. <i>Tr. 503, Hec. 659, etc</i>.<br><span><b>Étym</b>. σπείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπορα - σπορά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4702":"<h1>sporimos</h1>\n<p>Strong n° 4702 <i>Prononciation [spor'-ee-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui convient pour semer, semé</li>\n<li>champs ensemencés, récolte qui pousse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπόριμος, ος, ον</b> <span>[ῐ]</span><br><b>   I</b> <i>pass. :</i><br><b>      1</b> prêt <i>ou</i> propre à être ensemencé, XÉN. <i>Hell. 3, 2, 10 ;</i> THCR. <i>Idyl. 25, 219 ;</i> DS. <i>1, 36 ;</i> DH. <i>6, 17, etc. ;</i> ἡ σπόριμος (<i>s.-e</i>. γῆ) TH. <i>H.P. 6, 5, 4,</i> la terre préparée ;<br><b>      2</b> qui concerne l’ensemencement : σπόριμος μήν, PLUT. <i>M. 378</i> e, le mois des semailles ; ANTH. <i>6, 95 ;</i> τὰ σπόριμα, NT. <i>Matth. 12, 1 ;</i> GEOP. <i>1, 12, 37,</i> les semailles ;<br><b>   II</b> <i>act</i>. qui ensemence, <i>fig</i>. MAN. <i>3, 396</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -η, MAN. <i>l. c</i>.<br><span><b>Étym</b>. σπορά.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σποριμος - σπόριμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4703":"<h1>sporos</h1>\n<p>Strong n° 4703 <i>Prononciation [spro'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>les semailles</li>\n<li>la semence (utilisée dans les semailles)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπόρος, ου (ὁ) :<br>      1</b> ensemencement, HDT. <i>8, 109 ;</i> XÉN. <i>Œc. 7, 20 ;</i> PLAT. <i>Tim. 42</i> b ; PLUT. <i>M. 144</i> b ; <i>d’où</i> temps des semailles, XÉN. <i>Œc. 17, 4 ;</i> THCR. <i>Idyl. 10, 14 ;</i> PLAT. <i>Tim. 42</i> d ;<br><b>      2</b> semence, A. RH. <i>3, 413 ;</i> THCR. <i>Idyl. 25, 5 ;</i> ANTH. <i>11, 365 ;</i> PLUT. <i>M. 670</i> b ; <i>d’où</i> produit, HDT. <i>4, 53 ;</i> SOPH. <i>Ph. 706 ; particul</i>. semence génitale, HPC. <i>359, 41, etc. ;</i> PLUT. <i>M. 144</i> b ; <i>d’où fig</i>. rejeton, enfant, LYC. <i>221, 750, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. dor</i>. σπόρω, THCR. <i>Idyl. 10, 14</i>.<br><span><b>Étym</b>. σπείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπορος - σπόρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4704":"<h1>spoudazo</h1>\n<p>Strong n° 4704 <i>Prononciation [spoo-dad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se hâter, faire en hâte</li>\n<li>s'efforcer de, tâcher, faire diligence</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπουδάζω</b> <span>(<i>f</i>. άσομαι, <i>réc</i>. άσω, <i>ao</i>. ἐσπούδασα, <i>pf</i>. ἐσπούδακα, <i>pl.q.pf</i>. ἐσπουδάκειν ; <i>pass. f</i>. σπουδασθήσομαι, <i>ao</i>. ἐσπουδάσθην, <i>pf</i>. ἐσπούδασμαι)</span> <span>[ᾰ <i>fut., ao., pf. et pl.q.pf. act</i>.]</span><br><b>   I</b> être empressé, s’empresser, AR. <i>Th. 572, d’où :</i><br><b>      1</b> <i>avec un rég. de ch</i>. s’appliquer à, s’occuper activement de : περί τι, XÉN. <i>Cyr. 6, 1, 50, etc. ;</i> PLAT. <i>Rsp. 330</i> c, <i>etc. ;</i> ISOCR. <i>148</i> c, <i>etc. ;</i> DÉM. <i>66, 18, etc. ;</i> περί τινος, PLAT. <i>Ap. 24</i> c, <i>etc. ;</i> ISOCR. <i>281</i> e ; ἐπί τινι, XÉN. <i>Mem. 1, 3, 11 ;</i> PLAT. <i>Phædr. 276</i> b, <i>etc. ;</i> ISOCR. <i>23</i> c, DÉM. <i>514, 11, etc. ;</i> πρός τι, DÉM. <i>617, 10 ;</i> εἴς τι, DÉM. <i>574, 41 ;</i> τινί, LUC. <i>Par. 37, etc. ;</i> τι, XÉN. <i>Conv. 8, 17 ; Cyr. 6, 1, 48 ;</i> PLAT. <i>Phæd. 114</i> e, <i>etc. ;</i> ὑπέρ τινος, ISOCR. <i>108</i> b, <i>etc. ;</i> DÉM. <i>1371, 10,</i> de qqe ch. ; <i>avec un inf</i>. SOPH. <i>O.C. 1143 ;</i> EUR. <i>I.A. 337 ;</i> XÉN. <i>Cyr. 1, 3, 11 ;</i> PLAT. <i>Rsp. 336</i> e, <i>etc. ; avec</i> ὡς, XÉN. <i>Lac. 14, 4 ; avec</i> ὅπως, XÉN. <i>Eq. 11, 10 ;</i> DÉM. <i>1053, 21 ;</i> ARSTT. <i>Nic. 1, 7, etc</i>. s’efforcer de, <i>etc. ; avec un part. :</i> σπουδάζω διδάσκων, XÉN. <i>Œc. 9, 1,</i> je travaille à instruire (ma femme) ; <i>au pass</i>. être fait <i>ou</i> préparé <i>ou</i> obtenu avec peine, avec soin, XÉN. <i>Lac. 10, 3, etc. ;</i> PLAT. <i>Rsp. 485</i> e, <i>etc. ;</i> EUR. <i>Suppl. 761, etc. ; au pass. :</i> τὰ μάλα ἐσπουδασμένα σῖτα, XÉN. <i>Cyr. 4, 2, 38,</i> les mets les plus exquis ;<br><b>      2</b> <i>avec un rég. de pers</i>. être empressé auprès de, s’attacher à, s’intéresser à, prendre parti pour : περί τινα, XÉN. <i>Cyr. 5, 4, 13 ;</i> ISOCR. <i>4</i> a ; DÉM. <i>1389, 10 ;</i> PLUT. <i>Them. 2, etc. ;</i> πρός τινα, PLAT. <i>Gorg. 510</i> c, <i>etc. ;</i> DÉM. <i>624, 6 ;</i> ὑπέρ τινος, DÉM. <i>583, 2 ;</i> τινί, PLUT. <i>Artax. 21 ;</i> ARR. <i>Epict. 3, 4, 1, etc</i>. s’attacher à qqn, prendre soin de lui, de ses intérêts ; <i>au pass</i>. σπουδάζεσθαι ὑπό τινος, STR. <i>833 ;</i> PLUT. <i>Them. 5, Per. 24, etc. ; ou</i> πρός τινος, LUC. <i>D. deor. 16, 1, etc</i>. être aimé, recherché <i>ou</i> protégé par qqn ;<br><b>   II</b> être sérieux, AR. <i>Pl. 557 ; p. opp. à</i> παίζειν, PLAT. <i>Phædr. 234</i> d ; πρός τινα, XÉN. <i>Cyr. 1, 3, 11 ;</i> PLAT. <i>Rsp. 403</i> b ; DÉM. <i>515, 23 ;</i> ἐπί τινι, PLAT. <i>Phædr. 234</i> a ; περί τι, ISOCR. <i>8</i> e ; ἔν τινι, PLAT. <i>Theæt. 167</i> e ; PLUT. <i>M. 199</i> a, traiter sérieusement de qqe ch. ; <i>avec l’acc</i>. PLAT. <i>Gorg. 481</i> b, dire qqe ch. sérieusement ; <i>avec</i> ὅτι, PLAT. <i>Phædr. 236</i> b, prendre au sérieux que, <i>etc. ;</i> ἐσπουδακότι προσώπῳ, XÉN. <i>Conv. 2, 17,</i> avec un visage sérieux.<br><span><b><span class=\"arrow\"></span></b> <i>Fut</i>. σπουδάσομαι, PLAT. <i>Euthyphr. 3</i> e ; DÉM. <i>583, 2, etc. ;</i> σπουδάσω, POL. <i>3, 5, 8 ;</i> DS. <i>1, 58</i>.<br><span><b>Étym</b>. σπουδή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπουδαζω - σπουδάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 7 livres bibliques (NT)\n<ul>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G4705":"<h1>spoudaios</h1>\n<p>Strong n° 4705 <i>Prononciation [spoo-dah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>actif, diligent, zélé, sérieux</li>\n<li>très diligent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπουδαῖος, α, ον :<br>   I</b> <i>en parl. d’êtres animés :</i> empressé, diligent, <i>d’où :</i><br><b>      1</b> agile, rapide, POLL. <i>3, 149, etc. ; en parl. d’animaux,</i> POLL. <i>1, 197 ;</i><br><b>      2</b> actif, zélé, HDT. <i>8, 69 ;</i> XÉN. <i>Mem. 4, 2, 2 ;</i> PLAT. <i>1 Alc. 110</i> e, <i>etc. ;</i> ARSTT. <i>Rhet. 2, 4, etc. ; particul</i>. ardent à briguer une charge, PLUT. <i>Æmil. 2 ;</i><br><b>      3</b> sérieux, grave, XÉN. <i>Cyr. 2, 2, 16, etc. ;</i><br><b>      4</b> bon, vertueux, honnête, XÉN. <i>Hell. 3, 1, 9 ;</i> PLAT. <i>Rsp. 387</i> e, <i>etc. ; p. opp. à</i> φαῦλος, XÉN. <i>Cyr. 2, 2, 24 ;</i> PLAT. <i>Leg. 757</i> a, <i>etc. ;</i> ARSTT. <i>Poet. 2, 1 ; à</i> πονηρός, XÉN. <i>Hell. 2, 3, 19 ; à</i> μοχθηρός, ANTISTH. (PLUT. <i>Per. 1</i>) ;<br><b>   II</b> <i>en parl. de choses :</i><br><b>      1</b> qui se fait avec célérité, POLL. <i>3, 93 ;</i> τὸ σπ. POLYEN <i>6, 24, 1,</i> la rapidité ;<br><b>      2</b> fait avec zèle, avec soin, HDT. <i>2, 86 ; d’où</i> précieux, apprécié, SOPH. <i>O.C. 577 ;</i> TH. <i>H.P. 5, 3, 7 ;</i> ATH. <i>537 ;</i><br><b>      3</b> digne d’être recherché, convenable, HDT. <i>4, 23 ;</i> XÉN. <i>Mem. 4, 4, 23 ;</i> PLAT. <i>Leg. 668</i> a, <i>etc. ; p. opp. à</i> φαῦλος, PLAT. <i>Rsp. 519</i> d, <i>etc. ;</i><br><b>      4</b> sérieux, grave, XÉN. <i>Cyr. 2, 3, 1 et 20 ;</i> PLAT. <i>Euthyd. 300</i> e, <i>etc. ; p. opp. à</i> γελοῖος, AR. <i>Ran. 390 ; d’où</i> sérieux, important, THGN. <i>65, 70, 116, etc. ;</i> XÉN. <i>Hell. 1, 4, 12, etc. ;</i> PLAT. <i>Lach. 182</i> e, <i>etc</i>.<br><span>•<i> Cp</i>. σπουδαιότερος, XÉN. <i>Cyr. 2, 3, 20 ;</i> PLAT. <i>Rsp. 519</i> d, <i>etc. ; ou</i> -έστερος, HDT. <i>1, 8, 133 ;</i> <i>• Sup</i>. σπουδαιότατος, HDT. <i>2, 86 ;</i> XÉN. <i>Cyr. 2, 2, 16, etc. ;</i> PLAT. <i>Leg. 667</i> b, <i>etc. ;</i> DÉM. <i>791, 4 ; ou</i> -έστατος, HÉCAT. (EUST. <i>Od. 1441, 55</i>).<br><span><b>Étym</b>. σπουδή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπουδαιος - σπουδαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4706":"<h1>spoudaioteron</h1>\n<p>Strong n° 4706 <i>Prononciation [spoo-dah-yot'-er-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>très diligemment</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπουδαίως</b>, <i>adv. :</i><br><b>      1</b> en hâte, avec empressement, POLL. <i>3, 149 ;</i><br><b>      2</b> avec zèle, DL. <i>6, 27 ;</i><br><b>      3</b> avec diligence, avec soin, HDT. <i>2, 86 ;</i> ARSTT. <i>Rhet. 2, 4 ;</i> PLUT. <i>M. 963</i> b ;<br><b>      4</b> sérieusement, XÉN. <i>Cyr. 1, 3, 9 ;</i> PLAT. <i>Crat. 406</i> b.<br><span>•<i> Cp</i>. σπουδαιότερον, XÉN. <i>Cyr. 2, 3, 20 ;</i> PLAT. <i>Rsp. 536</i> c, <i>ou</i> σπουδαιοτέρως, PLUT. <i>l. c. ;</i> <i>• Sup</i>. σπουδαιότατα, HDT. <i>l. c</i>.<br><span><b>Étym</b>. σπουδαῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπουδαιοτερον - σπουδαίως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4707":"<h1>spoudaioteros</h1>\n<p>Strong n° 4707 <i>Prononciation [spoo-dah-yot'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>actif, diligent, zélé, sérieux</li>\n<li>très diligent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>σπουδαιότης, ητος (ἡ) :<br>      1</b> <i>en parl. de pers</i>. soin, diligence, empressement, PLAT. <i>Def. 412</i> e ;<br><b>      2</b> <i>en parl. de choses,</i> bonne qualité, DS. <i>1, 93</i>.<br><span><b>Étym</b>. σπουδαῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπουδαιοτερος - σπουδαιότερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4708":"<h1>spoudaioteros</h1>\n<p>Strong n° 4708 <i>Prononciation [spoo-dah-yot-er'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>hâtivement, à la hâte</li>\n<li>diligemment, sérieusement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>σπουδαιότης, ητος (ἡ) :<br>      1</b> <i>en parl. de pers</i>. soin, diligence, empressement, PLAT. <i>Def. 412</i> e ;<br><b>      2</b> <i>en parl. de choses,</i> bonne qualité, DS. <i>1, 93</i>.<br><span><b>Étym</b>. σπουδαῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπουδαιοτερως - σπουδαιοτέρως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4709":"<h1>spoudaios</h1>\n<p>Strong n° 4709 <i>Prononciation [spoo-dah'-yoce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>hâtivement, à la hâte</li>\n<li>diligemment</li>\n<li>sérieusement, instamment, avec instances</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπουδαίως</b>, <i>adv. :</i><br><b>      1</b> en hâte, avec empressement, POLL. <i>3, 149 ;</i><br><b>      2</b> avec zèle, DL. <i>6, 27 ;</i><br><b>      3</b> avec diligence, avec soin, HDT. <i>2, 86 ;</i> ARSTT. <i>Rhet. 2, 4 ;</i> PLUT. <i>M. 963</i> b ;<br><b>      4</b> sérieusement, XÉN. <i>Cyr. 1, 3, 9 ;</i> PLAT. <i>Crat. 406</i> b.<br><span>•<i> Cp</i>. σπουδαιότερον, XÉN. <i>Cyr. 2, 3, 20 ;</i> PLAT. <i>Rsp. 536</i> c, <i>ou</i> σπουδαιοτέρως, PLUT. <i>l. c. ;</i> <i>• Sup</i>. σπουδαιότατα, HDT. <i>l. c</i>.<br><span><b>Étym</b>. σπουδαῖος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπουδαιως - σπουδαίως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4710":"<h1>spoude</h1>\n<p>Strong n° 4710 <i>Prononciation [spoo-day']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>en hâte, avec empressement</li>\n<li>le sérieux, la gravité, de la diligence\n<ol type=\"a\">\n<li>sérieux dans l'accomplissement, la promotion, ou les efforts pour toute chose</li>\n<li>faire diligence, s'intéresser le plus sérieusement</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπουδή, ῆς (ἡ) :<br>   I</b> hâte, empressement, ESCHL. <i>Sept. 371, 374 ;</i> SOPH. <i>Ph. 637, etc. ;</i> XÉN. <i>Cyr. 2, 4, 6, etc. ;</i> σπ. ὁδοῦ, THC. <i>7, 77,</i> hâte de la marche ; σπουδῇ, en hâte, avec précipitation, vite, promptement, prestement, OD. <i>13, 279 ; 15, 209 ;</i> HDT. <i>9, 1, etc. ;</i> XÉN. <i>An. 6, 5, 14, etc. ;</i> PLAT. <i>Ep. 348, etc. ;</i> EUR. <i>Hipp. 903, 1152, etc. ;</i> πάνυ σπουδῇ, en grande hâte, en toute hâte, THC. <i>8, 89 ;</i> PLAT. <i>Phæd. 98</i> b ; πολλῇ σπουδῇ, XÉN. <i>Cyr. 4, 5, 12, etc. ;</i> σὺν πολλῇ σπουδῇ, XÉN. <i>An. 1, 8, 4, m. sign. ;</i> διὰ σπουδῆς, XÉN. <i>Hell. 6, 2, 28,</i> avec empressement ; κατὰ σπουδήν, THC. <i>1, 93 ; 2, 90, etc. ;</i> XÉN. <i>An. 7, 6, 28 ;</i> μετὰ σπουδῆς, HDN <i>3, 4, 1, etc. ;</i> ὑπὸ σπουδῆς, THC. <i>5, 66 ;</i> PLUT. <i>Rom. 8, etc. ;</i> σπουδῆς ὕπο, EUR. <i>Hel. 1004, m. sign. ;</i> σπουδὴν ἔχειν, avoir hâte, se dépêcher, HDT. <i>9, 89, etc. ;</i> πολλὴν σπουδὴν ἔχειν, avoir grande hâte, HDT. <i>9, 8 ; avec l’inf</i>. HDT. <i>6, 120 ;</i><br><b>   II</b> <i>p. suite,</i> effort, <i>particul. :</i><br><b>      1</b> effort pénible et contraint : μᾶλλον σπουδὴν ποιεῖσθαι, THC. <i>4, 30,</i> se hâter davantage ; ἄτερ σπουδῆς, OD. <i>21, 409,</i> sans peine ; <i>adv</i>., σπουδῇ, avec peine, avec effort, à peine, IL. <i>2, 99 ; 5, 893 ; 11, 562, etc. ;</i> OD. <i>3, 297 ; 24, 119 ;</i><br><b>      2</b> effort volontaire, zèle, ardeur : σπουδῇ, avec zèle, avec ardeur, PD. <i>O. 10 (11), 117 ;</i> EUR. <i>Ph. 849, etc. ;</i> THC. <i>3, 49 ;</i> PLAT. <i>Rsp. 388</i> d, <i>etc. ;</i> μετὰ σπουδῆς, PLAT. <i>Charm. 175</i> e, <i>etc. ;</i> σὺν σπουδῇ, PLAT. <i>Leg. 818</i> c, <i>etc. m. sign. ;</i> πολλῇ σπουδῇ, HDT. <i>1, 88 ;</i> XÉN. <i>Cyr. 4, 2, 38 ;</i> πάσῃ σπουδῇ, PLAT. <i>Leg. 952</i> a ; ἐπὶ μεγάλης σπουδῆς, PLAT. <i>Conv. 192</i> c, avec grande ardeur ; ἄξιος σπουδῆς, digne de zèle, qui mérite d’être recherché, SOPH. <i>O.R. 778 ;</i> PLAT. <i>Phædr. 277</i> e, <i>etc. ; p. suite,</i> qui a de la valeur, précieux, PLUT. <i>Ant. 75 ; en parl. de pers</i>. digne d’estime, XÉN. <i>Conv. 1, 6 ; au plur</i>. σπουδαὶ δεσποίνας, EUR. <i>Ion 1061,</i> le zèle <i>ou</i> les efforts de la maîtresse ; ξυμπάντων ἐρώτων σπουδαί, PLAT. <i>Leg. 632</i> a, l’effort de toutes les inclinations ; σπουδαὶ λόγων, EUR. <i>Hec. 132,</i> l’ardeur dans le discours ; οὐδεμία πολλὴ σπουδὴ τῆς μελέτης, HPC. <i>759</i> h, le traitement n’exige pas une si grande peine ; σπουδῆς πολλῆς τὰ πράγματα προσδεῖται, DÉM. <i>123, 3,</i> l’état présent des affaires demande beaucoup d’efforts ; σπουδὴ γίγνεται περί τι, PLAT. <i>Phædr. 276</i> e ; σπουδή ἐστι περί τινος, DÉM. <i>90, 10, etc.,</i> on met son zèle, on donne tout son soin à qqe ch. ; σπουδὴ πολλή (ἐστι) <i>avec l’inf</i>. HPC. <i>750</i> d, <i>m. sign. ;</i> σπουδὰν θεῖναι ἅπασαν ἀμφί τινος, PD. <i>P. 4, 492 ;</i> σπουδὴν θέσθαι χάριν τινός, SOPH. <i>Aj. 12 ;</i> μεγάλην σπουδὴν εἰσφέρειν εἴς τι, DS. <i>184 ;</i> ἐν σπουδῇ θέσθαι τι, PLUT. <i>Sol. 2, etc</i>. mettre tout son zèle, apporter toute sa bonne volonté, à qqe ch. ; se donner de la peine pour qqe ch. ; σπουδὴν ἔχειν, EUR. <i>I.T. 1433,</i> se donner de la peine, faire effort ; <i>avec le gén. de la chose pour laquelle on se donne de la peine,</i> EUR. <i>Alc. 778 ;</i> PLAT. <i>Euthyd. 306</i> c ; σπουδὴν ἔχειν εἴς τι, EUR. <i>Med. 557 ;</i> περί τινος. PLAT. <i>Riv. 136</i> c ; σπουδὴν ποιεῖσθαι περί τινος, PLAT. <i>Euthyd. 304</i> e, <i>etc. ;</i> περί τι, ISOCR. <i>91</i> b ; POL. <i>1, 46, 2, etc. ;</i> ἕνεκεν <i>ou</i> χάριν τινός, POL. <i>2, 37, 9, etc. ;</i> ἐπί τινι, LUC. <i>Salt. 1,</i> se donner de la peine, faire effort pour qqe ch. ; σπουδὴν ἔχειν <i>avec l’inf</i>. HDT. <i>9, 8 ;</i> EUR. <i>Ph. 901 ;</i> σπουδὴν ποιεῖσθαι <i>avec l’inf</i>. HDT. <i>1, 4 ; 7, 205, etc. ;</i> LYS. <i>102, 2,</i> se donner de la peine, faire effort pour ; σπουδὴν ἔχειν <i>avec une prop. inf</i>. HDT. <i>7, 149,</i> faire effort pour que, <i>etc. ;</i> σπουδὴν ἔχειν ὅπως, DH. <i>5, 149 Reiske ;</i> σπουδὴν ποιεῖσθαι ὅπως, DÉM. <i>1454, 11, m. sign. ;</i><br><b>      3</b> application réfléchie : σπουδῇ, PLAT. <i>Charm. 155</i> c, avec application, avec intention, exprès ;<br><b>      4</b> soin, attention scrupuleuse : σπουδῇ, DH. <i>5, 54 Reiske</i> (écrire) avec soin ;<br><b>      5</b> <i>particul</i>. zèle pour une personne, intérêt <i>ou</i> bienveillance pour qqn., soins affectueux, attachement, PLUT. <i>Cic. 9 ;</i> HDN <i>2, 10, 19, etc. ;</i> σπ. περί τινα, HDN <i>5, 4, 22, m. sign. ;</i> διὰ τὴν ἐμὴν σπουδήν, ANT. <i>146, 13,</i> par zèle pour moi ;<br><b>      6</b> ardeur pour obtenir qqe ch. ; poursuite d’une charge, brigue, PLUT. <i>Luc. 42 ; au plur</i>. PLAT. <i>Theæt. 173</i> d ; PLUT. <i>Crass. 7 ;</i> κατὰ σπουδάς, AR. <i>Eq. 1370,</i> par des intrigues ;<br><b>      7</b> exercice oratoire, dissertation, exposition, PHILSTR. <i>V. Ap. 4, 27 ; 6, 14 ;</i><br><b>      8</b> sérieux, gravité, <i>p. opp. à</i> γέλως, XÉN. <i>Conv. 1, 13 ; à</i> παιδιά, ARSTT. <i>Rhet. 3, 18, 3, etc. ; au plur. p. opp. à</i> παιδιαί, PLAT. <i>Leg. 647</i> d, <i>etc. ;</i> ἀπὸ σπουδῆς, IL. <i>7, 359 ; 12, 233,</i> sérieusement ; σπουδῇ, THC. <i>3, 49 ;</i> XÉN. <i>Cyr. 6, 1, 6, etc. ;</i> PLAT. <i>Leg. 828</i> d, <i>m. sign. ; p. opp. à</i> μετὰ γέλωτος, PLUT. <i>Per. 8 ;</i> σπουδῆς χάριν, <i>p. opp. à</i> παιδιᾶς ἕνεκα, PLAT. <i>Pol. 288</i> c, <i>m. sign. ;</i> μετὰ σπουδῆς, sérieusement, XÉN. <i>Conv. 1, 1 ;</i> PLAT. <i>Leg. 656</i> a, <i>etc. ; p. opp. à</i> μετὰ παιδιᾶς, PLAT. <i>Leg. 880</i> d, <i>etc. ;</i> σπουδὴν ποιεῖσθαι, AR. <i>Ran. 522,</i> considérer qqe ch. comme sérieux, le prendre au sérieux ; σπουδῇ παίζειν, XÉN. <i>Cyr. 6, 1, 6 ;</i> χαριεντίζεσθαι, PLAT. <i>Ap. 24</i> c, plaisanter avec un visage sérieux, plaisanter en gardant son sérieux.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σπουδά <span>[ᾱ]</span> PD. <i>l. c. etc. ; lac</i>. σποδά <span>[ᾱ]</span> AR. <i>Lys. 173 dout</i>.<br><span><b>Étym</b>. σπεύδω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπουδη - σπουδή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 7 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (5)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4711":"<h1>spuris</h1>\n<p>Strong n° 4711 <i>Prononciation [spoo-rece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une corbeille de roseau, (corbeille à repas, panier)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σπυρίς, ίδος (ἡ)</b> <span>[ῠῐδ]</span> corbeille <i>ou</i> panier tressé, de forme ronde, <i>particul</i>. pour le pain <i>ou</i> le poisson, HDT. <i>5, 16 ;</i> AR. <i>Pax 1005 ; au plur</i>. ANTIPH. (<i>Com. fr. 3, 18</i>) ; ARR. <i>Epict. 4, 10, 21 ;</i> ἀπὸ σπυρίδος δεῖπνα, ATH. <i>365</i> a, repas fait des provisions de chacun, pique-nique.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σπυρις - σπυρίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4712":"<h1>stadion</h1>\n<p>Strong n° 4712 <i>Prononciation [stad'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un espace ou distance d'environ 185 mètres</li>\n<li>une lutte à la course\n<ol type=\"a\">\n<li>lieu où les concurrents courraient, celui dépassant les autres et atteignant le but le premier recevant le prix. Des courses de ce type avaient lieu dans la plupart des grandes cités Grecques, et se courraient, comme à Olympie, sur une distance de 600 pieds, en mesure Grecque.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στάδιον, ου (τὸ)</b> <span>[ᾰ]</span><br><b>   I</b> le stade, <i>mesure de 600 pieds grecs ou 625 pieds romains,</i> HDT. <i>4, 101 ; 5, 53 ; 9, 23 ;</i> ATT. ; <i>fig</i>. ἑκατὸν σταδίοισιν ἄριστος, AR. <i>Nub. 430,</i> de cent stades (<i>càd</i>. de beaucoup) le meilleur ;<br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> carrière de la longueur d’un stade, <i>d’où</i> course dans le stade, THGN. <i>1306 ;</i> PD. <i>O. 10, 76 ; 13, 41, 50, etc. ;</i> τὸ στάδιον ἀγωνίζεσθαι, HDT. <i>5, 22 ;</i> XÉN. <i>An. 4, 8, 27 ; ou</i> ἀμιλλᾶσθαι, PLAT. <i>Leg. 833</i> a, disputer le prix de la course du stade ; τὸ στάδιον νικᾶν, XÉN. <i>Hell. 1, 2, 1,</i> remporter le prix du stade ;<br><b>      2</b> vaste espace pour la danse, EUR. <i>Ion 497 ;</i><br><b>      3</b> <i>p. anal</i>. jeu de trictrac <i>ou</i> d’échecs, <i>comparé au stade dans lequel s’exercent les lutteurs,</i> ANTH. <i>15, 18</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Contracté en</i> στάδιν, <i>dans une inscr. att</i>. CIA. <i>3, 1223, d, 3, 6, add. 238, a, 9, b, 6 ; v. Meisterh. p. 58, § 26, 4 ; plur. hétérog</i>. στάδιοι, <i>dans une inscr. att. du 4<sup>e</sup> siècle av. J.C. ; v. Meisterh. p. 113, 12</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σταδιον - στάδιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4713":"<h1>stamnos</h1>\n<p>Strong n° 4713 <i>Prononciation [stam'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parmi les Grecs, une jarre en terre, dans lequel se conservait le vin, mais aussi utilisée à d'autres usages\n<ol type=\"a\">\n<li>du petit vase dans lequel de la manne était gardée, posé dans l'arche de l'alliance</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στάμνος, ου (ὁ) :<br>      1</b> cruche de terre pour le vin, AR. <i>Pl. 545, fr. 448 Dind. ;</i> DÉM. <i>933, 25, etc. ;</i><br><b>      2</b> cruche, <i>en gén</i>. HPC. <i>1234</i> b.<br><span><b><span class=\"arrow\"></span></b> ἡ στ. HERMIPP. (<i>Com. fr. 2, 410</i>) ; ERATOSTH. (ATH. <i>499</i> e).<br><span><b>Étym</b>. <i>indo-europ</i>. *sth₂-mn-o- « ce qui se tient debout », <i>v</i>. ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σταμνος - στάμνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4714":"<h1>stasis</h1>\n<p>Strong n° 4714 <i>Prononciation [stas'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une position, un rang, une halte, un état</li>\n<li>une insurrection</li>\n<li>une lutte, une sédition</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στάσις, εως (ἡ)</b> <span>[ᾰ]</span><br><b>A</b> <i>tr. :</i><br><b>      1</b> action de poser debout, de dresser, pose <i>en gén. (de filets,</i> XÉN. <i>Cyn. 2, 8 ; d’échelles,</i> POL. <i>5, 60, 7 ; de tentes,</i> PLUT. <i>Ant. 9, etc</i>.) ;<br><b>      2</b> action de peser, AR. <i>Ran. 1401 ;</i><br><b>B</b> <i>intr. :</i><br><b>   I</b> action de se tenir, <i>d’où :</i> stabilité, fixité, PLAT. <i>Crat. 426</i> d ; <i>p. opp. à</i> κίνησις, PLAT. <i>Soph. 250</i> c, <i>etc. ;</i> PLUT. <i>M. 945</i> f, <i>etc. ; à</i> βάσις, PLAT. <i>Crat. 437</i> a, <i>etc. ; à</i> φορά, PLUT. <i>M. 1012</i> f ; στάσις μελῶν, AR. <i>Ran. 1281, c</i>. τὸ στάσιμον (<i>v</i>. στάσιμος) ; στάσις ὀμμάτων, HPC. <i>394, 7,</i> la fixité des yeux, le regard fixe ; <i>abs</i>. στάσις, HPC. <i>394, 16,</i> l’arrêt <i>ou</i> la suspension des fonctions vitales, l’engourdissement ;<br><b>   II</b> la place où qqe ch. se tient, le lieu où l’on se tient, le lieu : στάσιν ἔχειν, HDT. <i>9, 24 ;</i> AR. <i>Pl. 953,</i> prendre un lieu <i>ou</i> une place où se tenir ; κατὰ τὴν ἐξ ἀρχῆς στάσιν μένειν, POL. <i>2, 68, 7,</i> rester à la place qu’on occupe depuis le commencement ; στ. δικτύων, XÉN. <i>Cyn. 9, 16,</i> l’endroit où sont posés les filets ; στ. ἵππων, EUR. <i>Hipp. fr. 445 Nauck,</i> le lieu où se tiennent les chevaux, écurie ; <i>cf</i>. EPHIPP. (<i>Com. fr. 3, 337) ; particul</i>. le lieu <i>ou</i> le point où sont situés les principaux points cardinaux, HDT. <i>2, 26 ;</i><br><b>   III</b> attitude, EUR. <i>Bacch. 925 ;</i> PLAT. <i>Phædr. 253</i> d ; τῇ στάσει κάμνειν, ARSTT. <i>H.A. 5, 1,</i> être fatigué de la position qu’on a ; στάσις χοροῦ, <i>c</i>. χορός, le chœur, ESCHL. <i>Eum. 311 ; fig</i>. position, état, situation, <i>particul. :</i><br><b>      1</b> <i>au sens phys</i>. στ. ἀνέμου, état du vent (calme <i>ou</i> tempétueux) POL. <i>1, 48, 2 ; 1, 75, 8 ; 9, 25, 3 ;</i> ἀνέμων στάσις, ALC. <i>18, 2,</i> soulèvement des vents, tempête ; οἱ ἐτησίαι στάσιν ἔχουσι, POL. <i>5, 5, 3,</i> les vents se fixent, <i>càd</i>. durent, soufflent d’une manière continue ;<br><b>      2</b> état politique, situation d’un État, POL. <i>16, 34, 11 ;</i><br><b>      3</b> position d’une personne dans une société, situation d’un simple particulier, d’un philosophe, <i>etc</i>. ARR. <i>Epict. 1, 21, 1 ;</i><br><b>      4</b> position morale, état moral, POL. <i>10, 33, 6 ;</i><br><b>      5</b> état d’opinion, doctrine, école philosophique, PLUT. <i>Cic. 4 ;</i> SEXT. <i>P. 2, 48 ; 3, 32, etc. ;</i><br><b>   IV</b> action de se lever, <i>d’où :</i><br><b>      1</b> soulèvement, révolte : στάσιν τιθέναι, EUR. <i>H.f. 590 ;</i> ἐπεγείρειν, SOL. <i>fr. 3 (13), 19 Bgk ;</i> ἀνεγείρειν, AR. <i>Ran. 359,</i> exciter une révolte ; στάσεις ποιεῖν, ἐμποιεῖν, ISOCR. <i>178</i> e, <i>103</i> d, causer des troubles ; στάσεις παύειν, XÉN. <i>Mem. 4, 6, 14,</i> faire cesser les divisions politiques ;<br><b>      2</b> division politique entre deux personnes, PLUT. <i>Arist. 8 ;</i><br><b>      3</b> différend, querelle, dispute, SOPH. <i>O.R. 634 ;</i> ἐς λόγου στάσιν ἐλθεῖν, SOPH. <i>Tr. 1179,</i> en venir à une dispute ; <i>cf</i>. THC. <i>7, 33 ;</i> PLAT. <i>Rsp. 440</i> e ;<br><b>      4</b> différence d’opinion, dissentiment, désaccord, ESCHL. <i>Pers. 738 ;</i> DL. <i>3, 51 ;</i><br><b>      5</b> tempête : στ. κυμάτων, soulèvement des flots par la tempête, A. TAT. <i>3, 2 ;</i> στ. ἀντίπνους (πνευμάτων) ESCHL. <i>Pr. 1088,</i> lutte des tempêtes, orage, tourmente ;<br><b>      6</b> <i>p. ext</i>. ceux qui forment un parti politique, <i>c</i>. στασιῶται, le parti, HDT. <i>1, 59, 173 ;</i> ARSTT. <i>Œc. 2, p. 1348</i> a, <i>36 ;</i> DH. <i>6, 57, 65 ; avec un gén</i>. ἡ τοῦ Μαρίου στ. PLUT. <i>Sert. 4,</i> le parti de Marius ;<br><b>   V</b> ce qu’on pose debout, ce qui est posé, dressé, fixé, <i>d’où :</i><br><b>      1</b> colonne, pilier, <i>c</i>. στήλη, SPT. <i>Judith 9, 6 ;</i><br><b>      2</b> <i>fig</i>. statut, édit, décret, SPT. <i>Dan. 6, 7</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *sth₂-ti-, <i>lat</i>. statiō ; <i>v</i>. ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στασις - στάσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (5)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4715":"<h1>stater</h1>\n<p>Strong n° 4715 <i>Prononciation [stat-air']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un statère, une pièce de monnaie\n<ol type=\"a\">\n<li>dans le N.T. un statère d'argent équivalait à 4 drachmes grecques ou 4 deniers romains, un sicle Juif</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στατήρ, ῆρος (ὁ)</b> <span>[ᾰ]</span><br><b>A</b> statère, <i>poids et monnaie :</i><br><b>   I</b> <i>poids :</i><br><b>      1</b> poids d’une livre (λίτρα) POLL. <i>4, 173 ;</i><br><b>      2</b> poids d’une mine (μνᾶ) EUP. <i>2-1, 529 Meineke ;</i><br><b>   II</b> <i>monnaie :</i><br><b>      1</b> statère d’argent, <i>de 4 drachmes à Athènes,</i> LEX. ;<br><b>      2</b> statère d’or <i>de 20 drachmes à Athènes,</i> XÉN. <i>An. 1, 7, 18 ;</i> PLAT. <i>Euthyd. 299</i> e ; <i>de 28 drachmes à Cyzique,</i> DÉM. <i>914, 11 ; cf</i>. THC. <i>4, 52 ;</i> XÉN. <i>An. 5, 6, 23 ; autres de valeur diverse, en Perse</i> (<i>v</i>. Δαρεικοί), <i>en Lydie,</i> HDT. <i>1, 54, etc. ;</i><br><b>B</b> débiteur, <i>c</i>. χρεώστης, EPICH. <i>fr. 79 Ahrens</i>.<br><span><b>Étym</b>. ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στατηρ - στατήρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4716":"<h1>stauros</h1>\n<p>Strong n° 4716 <i>Prononciation [stow-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un pieu droit, spéc. pointu</li>\n<li>une croix\n<ol type=\"a\">\n<li>l'instrument bien connu du châtiment le plus cruel et le plus ignominieux, emprunté par les grecs et les Romains aux Phéniciens ; depuis le temps de Constantin le Grand, étaient attachés à la croix les pires criminels, les plus bas des esclaves, les voleurs, les fauteurs de troubles, et même, dans certaines provinces, selon le bon plaisir des gouverneurs, des hommes justes et paisibles, et quelquefois des citoyens Romains</li>\n<li>la crucifixion que Christ a subie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σταυρός, οῦ (ὁ) :<br>   I</b> pieu pour une palissade, palissade, IL. <i>24, 453 ;</i> OD. <i>14, 11 ;</i> THC. <i>4, 90 ;</i> XÉN. <i>An. 5, 2, 21 ;</i> pieu pour fondement d’une construction, HDT. <i>5, 16 ;</i> THC. <i>7, 25, etc. ;</i><br><b>   II</b> instrument de supplice, <i>particul. :</i><br><b>      1</b> pal, PLUT. <i>Artax. 17 ;</i><br><b>      2</b> poteau pour y clouer les condamnés, DS. <i>2, 18 ;</i> PLUT. <i>M. 554</i> a ; LUC. <i>Per. 34 ; particul</i>. poteau avec une traverse, <i>d’où</i> croix, LUC. <i>J. voc. 12 ;</i> NT. <i>Matth. 10, 38 ; Luc. 9, 23 ; 14, 27</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *steh₂-u-, pieu, <i>cf. lat</i>. īnstaurō ; <i>v</i>. ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σταυρος - σταυρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 27 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (4)</li>\n<li>Luc (3)</li>\n<li>Jean (4)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4717":"<h1>stauroo</h1>\n<p>Strong n° 4717 <i>Prononciation [stow-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>garnir de pieux, dresser des pieux</li>\n<li>fortifier de pieux dressés, monter une palissade</li>\n<li>crucifier\n<ol type=\"a\">\n<li>crucifier quelqu'un</li>\n<li>métaph. crucifier la chair, détruire entièrement son pouvoir (la nature de la figure impliquant que la destruction se fait avec une peine intense)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σταυρόω-ῶ :<br>      1</b> élever une palissade, THC. <i>7, 25 ; p. suite,</i> garnir d’une palissade, DS. <i>Exc. 507, 69 ; au pass</i>. THC. <i>6, 100 ;</i><br><b>      2</b> crucifier, POL. <i>1, 86, 4 ;</i> NT. <i>Matth. 20, 19, etc. ; fig</i>. NT. <i>Gal. 5, 24, etc</i>.<br><span><b>Étym</b>. σταυρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σταυροω - σταυρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 42 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (8)</li>\n<li>Luc (6)</li>\n<li>Jean (11)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4718":"<h1>staphule</h1>\n<p>Strong n° 4718 <i>Prononciation [staf-oo-lay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>raisins, grappes de raisins</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σταφυλή, ῆς (ἡ)</b> <span>[ᾰῠ]</span><br><b>      1</b> grappe de raisin mûr, IL. <i>18, 561 ;</i> OD. <i>5, 69 ; 7, 121 ; 24, 343, etc. ;</i> PLAT. <i>Leg. 844</i> e, <i>etc. ;</i> TH. <i>H.P. 3, 18, 11, etc. ; p. opp. à</i> ὄμφαξ <i>et à</i> σταφίς, ANTH. <i>5, 304 ;</i><br><b>      2</b> tumeur à la luette, ARSTT. <i>H.A. 1, 11, 12</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. plur. épq</i>. σταφυλῇσι, IL. <i>18, 561 ;</i> OD. <i>5, 69, etc</i>.<br><span><b>Étym</b>. <i>pré-grec ; cf</i>. στέμφυλον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σταφυλη - σταφυλή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4719":"<h1>stachus</h1>\n<p>Strong n° 4719 <i>Prononciation [stakh'-oos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un épi de blé ou de grain qui pousse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στάχυς, υος (ὁ)</b> <span>[ᾰ, ῡ <i>aux cas dissyll. chez les Att.,</i> ῠ <i>chez les poètes postér. v. ci-dessous ;</i> ῠ <i>aux cas trisyll</i>.]</span><br><b>      1</b> épi, <i>particul</i>. épi de blé, IL. <i>23, 598 ;</i> HÉS. <i>O. 471 ;</i> ESCHL. <i>Suppl. 761 ; fr. 304, 305 ;</i> SOPH. <i>fr. 462</i> b, <i>etc. ; au plur</i>. AR. <i>Eq. 393 ;</i> ARSTT. <i>Pol. 3, 13, 17 ; p. anal</i>. épi de la Vierge, <i>étoile,</i> ARAT. <i>97 ; au plur</i>. MAN. <i>2, 134 ; fig</i>. fruit, rejeton, <i>en parl. de choses,</i> ESCHL. <i>Pers. 821 ; en parl. de pers</i>. EUR. <i>fr. 362, 22 ;</i> ORPH. <i>Arg. 216 ;</i> MAN. <i>6, 304 ;</i> NONN. <i>D. 18, 267, etc. ;</i><br><b>      2</b> épiaire, <i>plante,</i> DIOSC. <i>3, 120 ;</i><br><b>      3</b> νάρδου στάχυς, épinard, GEOP. <i>7, 13, 1 ;</i><br><b>      4</b> sorte de bandage, ORIB. <i>106 Mai</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῡ]</span> <i>aux cas dissyll</i>. CALL. <i>Dian. 130 ;</i> A. RH. <i>1, 688 ; 3, 1338, 1389, etc. ;</i> THCR. <i>Idyl. 10, 47, etc. Dat. plur. épq</i>. σταχύεσσι, IL. <i>l. c</i>.<br><span><b>Étym</b>. <i>pré-grec ; cf</i>. ἄσταχυς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σταχυς - στάχυς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4720":"<h1>Stachus</h1>\n<p>Strong n° 4720 <i>Prononciation [stakh'-oos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Stachys = « un épi de blé »\n<ol><li>chrétien de Rome, au nom grec, salué par Paul ; il a peut-être été l'évêque de Byzance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nVoir <b>, υος (ὁ)</b>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σταχυς - Στάχυς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4721":"<h1>stege</h1>\n<p>Strong n° 4721 <i>Prononciation [steg'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>un toit : d'une maison</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στέγη, ης (ἡ) :<br>   I</b> toit, ESCHL. <i>Ag. 897, etc. ;</i> HDT. <i>6, 27 ;</i> XÉN. <i>Cyr. 6, 3, 25 ; Mem. 3, 8, 9 ;</i><br><b>   II</b> tout édifice couvert, <i>particul. :</i><br><b>      1</b> maison, ESCHL. <i>Ag. 3, etc. ;</i> SOPH. <i>O.R. 637, etc. ;</i> XÉN. <i>Cyr. 6, 1, 14 ; An. 4, 4, 14 ; Conv. 1, 12 ; Œc. 7, 19 ;</i> κατὰ στέγας, SOPH. <i>El. 282,</i> à la maison ;<br><b>      2</b> chambre, HDT. <i>2, 148, 175 ;</i> XÉN. <i>Œc. 8, 13 ;</i><br><b>      3</b> terrier, SOPH. <i>fr. 184 Dind. ;</i><br><b>      4</b> tente, SOPH. <i>Aj. 108 ;</i><br><b>      5</b> tombeau, SOPH. <i>Ant. 1100 ;</i><br><b>      6</b> tillac d’un navire, <i>seul. lat</i>. stega, PLAUT. <i>Bacch. 2, 3, 44 ; Stich. 3, 1, 12</i>.<br><span><b>Étym</b>. στέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στεγη - στέγη</font>\n<br><br>renforcement du mot tegos (ornement d'un immeuble)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4722":"<h1>stego</h1>\n<p>Strong n° 4722 <i>Prononciation [steg'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>toiture, toit, couverture\n<ol type=\"a\">\n<li>protéger ou garder en recouvrant, préserver</li>\n</ol>\n</li>\n<li>couvrir du silence\n<ol type=\"a\">\n<li>garder secret</li>\n<li>cacher, dissimuler\n<ol>\n<li>erreurs et fautes des autres</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>recouvrir ou garder quelque chose par des menaces, supporter, endurer, montrer de la patience</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στέγω</b> <span>(<i>impf</i>. ἔστεγον, <i>f</i>. στέξω, <i>ao</i>. ἔστεξα, <i>pf. inus. ; pass. seul. prés. et ao</i>. ἐστέχθην)</span><br><b>   I</b> couvrir, <i>càd. :</i><br><b>      1</b> <i>litt</i>. couvrir, recouvrir, <i>acc</i>. AR. <i>Vesp. 1295 ;</i><br><b>      2</b> protéger, défendre, ESCHL. <i>Sept. 797 ;</i> SOPH. <i>O.C. 15 ;</i> XÉN. <i>Cyr. 7, 1, 33 ;</i><br><b>      3</b> cacher, tenir caché, SOPH. <i>O.R. 341, Ph. 136 ;</i> EUR. <i>El. 273 ;</i> PLAT. <i>Leg. 714</i> a ; <i>au pass</i>. être tenu caché, THC. <i>6, 72 ;</i> SOPH. <i>Tr. 596 ;</i><br><b>      4</b> contenir, renfermer, EUR. <i>I.A. 888 ;</i> PLAT. <i>Tim. 78</i> a ; ARSTT. <i>Probl. 8, 19, etc. ; particul</i>. tenir renfermé, ne pas laisser échapper, <i>en parl. d’eau, d’humidité :</i> ἀγγεῖον οὐδὲν τὸ ὕδωρ στέγει, PLAT. <i>Rsp. 621</i> a, aucun vase ne contient cette eau sans qu’elle s’échappe ;<br><b>   II</b> supporter, résister à, <i>acc</i>. ARSTT. <i>fr. 209 ;</i> POL. <i>3, 53, 2, etc. ;</i> DS. <i>3, 34 ;</i> JOS. <i>A.J. 5, 8, 12 ; d’où en gén</i>. supporter, <i>acc</i>. NT. <i>1Cor. 13, 7 ; particul. en parl. de l’eau :</i> δόμος ἅλα στέγων, ESCHL. <i>Suppl. 134,</i> maison qui empêche l’eau de la mer de pénétrer, <i>càd</i>. un navire ; νῆες οὐδὲν στέγουσαι, THC. <i>2, 94,</i> vaisseaux qui n’empêchent rien de pénétrer, <i>càd</i>. qui font eau de toutes parts ; <i>p. suite, abs</i>. devenir <i>ou</i> être imperméable, PLAT. <i>Criti. 111</i> d ; TH. <i>H.P. 5, 7, 4, etc. ; d’où</i> empêcher de pénétrer, repousser, ESCHL. <i>Sept. 216, 1009 ;</i> AR. <i>Vesp. 1295 ;</i><br><b><i>Moy</i>. στέγομαι</b> <span>(<i>impf</i>. ἐστεγόμην, <i>ao</i>. ἐστεξάμην)</span> écarter de soi, repousser, contenir, <i>acc</i>. PD. <i>P. 4, 144 ;</i> ANTH. <i>13, 27</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *(s)teg-, couvrir, toit ; <i>cf</i>. στέγη, τέγη, στέγος, τέγος, <i>lat</i>. tegō, <i>all</i>. Dach.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στεγω - στέγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n<li>1 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G4723":"<h1>steiros</h1>\n<p>Strong n° 4723 <i>Prononciation [sti'-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>difficile, rude\n<ol type=\"a\">\n<li>d'hommes ou d'animaux</li>\n</ol>\n</li>\n<li>stérile\n<ol type=\"a\">\n<li>de femmes qui ne peuvent concevoir d'enfant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στεῖρος</b>, <i>adj. f. c</i>. στεῖρα², <i>en parl. d’animaux,</i> EUR. <i>Andr. 711 ; masc. en parl. d’eunuques,</i> MAN. <i>1, 125</i>.<br><span><b>Étym</b>. <i>cf</i>. στεῖρα².</span><br><br>\n➀ <b>στεῖρα</b>, <i>ion</i>. <b>στείρη, ης (ἡ)</b> étrave d’un navire, <i>pièce de bois forte, recourbée en dedans et plantée à l’extrémité intérieure et dans le plan de la quille qu’elle continue,</i> IL. <i>1, 482 ;</i> OD. <i>2, 428</i>.<br><span><b>Étym</b>. <i>format. fém., cf</i>. στερεός.</span><br><br>\n➁ <b>στεῖρα, ας</b>, <i>adj. f</i>. stérile, <i>en parl. d’animaux,</i> OD. <i>10, 522 ; 11, 30 ; en parl. de femmes,</i> SPT. <i>Gen. 11, 30 ; 25, 21 ;</i> NT. <i>Luc. 1, 7, 36 ;</i> ANTH. <i>7, 468 ;</i> ORPH. <i>Lith. 453, etc</i>.<br><span><b>Étym</b>. <i>p</i>. *στέρϳα, <i>indo-europ</i>. *ster-ih₂, stérile, <i>cf</i>. στεῖρος, στερεός, στέριφος, <i>sscr</i>. starī́-, vache stérile, <i>lat</i>. sterilis.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στειρος - στεῖρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4724":"<h1>stello</h1>\n<p>Strong n° 4724 <i>Prononciation [stel'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre, placer, mettre en ordre, arranger\n<ol type=\"a\">\n<li>ajuster, préparer, équiper</li>\n<li>se préparer</li>\n<li>s'équiper pour son propre usage</li>\n</ol>\n</li>\n<li>amener ensemble, contracter, raccourcir\n<ol type=\"a\">\n<li>diminuer, modérer, faire cesser</li>\n<li>cesser d'exister</li>\n<li>se déplacer, se retirer, s'en aller</li>\n<li>s'abstenir de relation familière avec quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στέλλω</b> <span>(<i>f</i>. στελῶ, <i>ao</i>. ἔστειλα, <i>pf</i>. ἔσταλκα, <i>pl.q.pf</i>. ἐστάλκειν, <i>pass. f. inus., ao.2</i> ἐστάλην <span>[ᾰ]</span>, <i>pf</i>. ἔσταλμαι, <i>pl.q.pf</i>. ἐστάλμην)</span><br><b>A <i>tr</i>.<br>   I</b> équiper, préparer : νῆα, OD. <i>2, 287 ; 14, 247, 248 ;</i> πλοῖον, HDT. <i>3, 52, etc</i>. équiper un navire, στρατόν, ESCHL. <i>Pers. 177 ;</i> EUR. <i>I.A. 661,</i> équiper une armée ; πόλεμον, DH. <i>8, 51</i> préparer une guerre ; <i>particul. :</i><br><b>      1</b> armer <i>ou</i> disposer pour le combat : ἑτάρους, IL. <i>4, 294,</i> des compagnons ; τινὰ ἐς μάχην, IL. <i>12, 325,</i> armer <i>ou</i> disposer qqn pour un combat ;<br><b>      2</b> habiller, vêtir : τινὰ ἐσθῆτι, HDT. <i>3, 14 ; avec double acc</i>. στ. τινὰ στολήν, EUR. <i>Bacch. 827,</i> vêtir qqn d’une robe, <i>ou simpl</i>. στ. τινά., XÉN. <i>Hell. 5, 4, 5,</i> habiller qqn ; <i>d’où au pass</i>. οὗτοι οὕτω ἐστάλαται, HDT. <i>7, 89,</i> c’est ainsi qu’ils sont vêtus ; ἐσταλμέναι στολῇ, PLAT. <i>Leg. 833</i> d, revêtues d’une robe ;<br><b>      3</b> préparer à un voyage <i>ou</i> à une expédition, engager à voyager, à venir, <i>d’où</i> faire venir, mander, <i>acc</i>. SOPH. <i>O.R. 860, O.C. 298 ; avec l’inf</i>. οἵ σ' ἐν λιταῖς στείλαντες ἐξ οἴκων μολεῖν, SOPH. <i>Ph. 60,</i> qui t’invitant instamment à venir, <i>etc. ;</i> στ. τινὰ πομποῖς ἱκέσθαι, SOPH. <i>Ant. 165, etc.,</i> convier qqn à venir, en lui envoyant des messagers ; <i>au pass</i>. être mandé, SOPH. <i>O.C. 550 ;</i><br><b>      4</b> amener, emmener : τινὰ βίᾳ, SOPH. <i>Ph. 983,</i> emmener qqn de force ; στ. τινὰ σκάφει, EUR. <i>I.T. 982,</i> emmener sur un vaisseau ; στ. ἀπὸ κοινοῦ, LUC. <i>Per. 13,</i> envoyer qqn de la commune, <i>càd</i>. envoyer un député : στέλλειν τινὰ πάλιν εἰς οἶκον, ESCHL. <i>Pr. 387,</i> ramener qqn à la maison ; στ. εἰς Ἀχαιούς, SOPH. <i>Ph. 623,</i> conduire en Grèce ;<br><b>      5</b> envoyer : τινὰ εἰς, <i>acc</i>. ATT. qqn dans, <i>etc. ;</i> ναῦς περί, <i>acc</i>. THC. <i>7, 20,</i> des vaisseaux autour de, <i>etc. ; fig</i>. ἡ ὁδὸς εἰς Ἰνδοὺς ἄγουσα εἰς Κόρινθον στέλλει, LUC. <i>Herm. 27,</i> le chemin qui mène aux Indes conduit à (<i>litt</i>. met en route pour) Corinthe ;<br><b>   II</b> conduire, accompagner, escorter (un mort) <i>d’où</i> enterrer un mort, A. RH. <i>3, 205 ;</i><br><b>   III</b> amener à soi, <i>en gén</i>. στ. ἱστία, OD. <i>3, 11 ; 16, 353,</i> carguer les voiles ; <i>p. ext</i>. restreindre, réprimer, arrêter : τὴν κοιλίαν, A. APHR. <i>Probl. præf</i>. le flux de ventre, amener la constipation ; <i>fig</i>. στ : τὴν φυσῶσαν οἴησιν, PHIL. <i>2, 274,</i> réprimer la présomption ; <i>au pass</i>. φλέϐες στέλλοντο, NIC. <i>Al. 193,</i> les veines se contractaient, se resserraient ;<br><b>B <i>intr. :</i><br>      1</b> se préparer à partir, SOPH. <i>Ph. 571 ;</i><br><b>      2</b> aller, partir, HDT. <i>4, 148 ; 5, 125 ;</i> SOPH. <i>Ph. 640 ;</i> ἐκ δόμων ἔστειλα, ESCHL. <i>Pers. 609,</i> je suis venue de mon palais ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. στελοῦμαι, <i>ao</i>. ἐστειλάμην)</span><br><b>   I <i>intr. :</i><br>      1</b> s’équiper, se préparer : κατὰ στρατόν, IL. <i>23, 285,</i> dans l’armée ; ἐπ' ἄγραν, ANTH. <i>7, 535 ;</i> ἐς ἄγραν, LYC. <i>604,</i> se mettre en chemin, partir pour la chasse, pour la pêche ; ἐπί τι, EUR. <i>Hipp. 234 ;</i> περί τι, EUR. <i>Bacch. 998 ;</i> πρός τι, PLAT. <i>Phil. 50</i> e, <i>etc</i>. se préparer en vue de qqe ch. ; <i>avec un inf. :</i> κινεῖν κώπας, EUR. <i>Tr. 181,</i> se préparer à mouvoir les rames ; <i>cf</i>. HDT. <i>3, 124 ;</i><br><b>      2</b> <i>particul</i>. s’habiller, se vêtir : μελαίνῃ ἐσθῆτι, LUC. <i>Philops. 32,</i> d’une robe noire ; ἀμφὶ χρωτὶ πέπλους, EUR. <i>Bacch. 821,</i> jeter un manteau autour de son corps ;<br><b>      3</b> se préparer pour un voyage, <i>d’où</i> aller, venir (sur terre <i>et</i> sur mer) : στέλλου, κομίζου, ESCHL. <i>Pr. 392,</i> apprête-toi et va ; τούτων εἵνεκ' ἐστάλην, SOPH. <i>Aj. 328,</i> c’est pour cela que je suis venue ; ἐστάλην εὐθὺ τῆς πόλεως, LUC. <i>Nigr. 2,</i> je me suis mis directement en route pour la ville ; ποῖ στέλλεσθε ; EUR. <i>Hec. 117,</i> où allez-vous ? οἷπερ ἐστάλην ὁδοῦ, SOPH. <i>El. 404,</i> vers où je me suis mis en chemin, où j’avais l’intention d’aller ; στέλλεσθαι οἴκαδε, EUR. <i>Tr. 1264 ;</i> πρὸς οἴκους, EUR. <i>Hel. 440,</i> aller dans son pays ; <i>de même avec</i> ἐς <i>et l’acc</i>. HDT. <i>1, 165, etc. ; avec</i> ἐπί <i>et l’acc</i>. HDT. <i>7, 2, 239 ; avec le simple acc</i>. EUR. <i>Med. 666, H.f. 109 ;</i> στ. ἐπί τι, sortir vers qqe ch., partir <i>ou</i> faire voile vers un but, HDT. <i>5, 45 ;</i> XÉN. <i>An. 5, 1, 5 ; fig</i>. ἀπὸ θεσφάτων τίς ἀγαθὰ φάτις βροτοῖς στέλλεται ; ESCHL. <i>Ag. 1133,</i> quel savoir vient aux hommes provenant des prophéties ? ;<br><b>      4</b> ramener à soi : στ. ἱστία, IL. <i>1, 433 ;</i> ARSTT. <i>Mech. 7, etc</i>. carguer les voiles ; <i>abs</i>. POL. <i>6, 44, 6 ;</i> στ. χιτῶνα, HÉS. <i>Sc. 288,</i> relever <i>ou</i> retrousser son vêtement (pour travailler) ; <i>p. ext</i>. restreindre, comprimer : λόγον, EUR. <i>Bacch. 669,</i> restreindre sa parole ; <i>d’où abs</i>. se contenir, se retenir, POL. <i>8, 22, 4 ;</i> ANTH. <i>11, 149 ;</i> οὔτ' ἂν ἀπόσχοιντο οὐδενὸς οὐδὲ στείλαιντο, HPC. <i>10, 13,</i> ils ne s’abstiendraient ni ne se retiendraient de rien, <i>càd</i>. ne reculeraient devant rien ; <i>avec</i> μή, NT. <i>2Cor. 8, 20,</i> reculer par crainte que, craindre que ;<br><b>   II <i>tr. :</i><br>      1</b> faire venir, mander : τινα οἴκους, SOPH. <i>O.R. 434,</i> faire venir qqn dans sa maison ;<br><b>      2</b> préparer : στόλον, πλοῦν, ARR. <i>An. 5, 17, 14,</i> une expédition par mer.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. épq</i>. στελέω, OD. <i>2, 287 ; fut. éol</i>. σπολέω, SAPPH. <i>fr. 50 Bgk ; ao. épq</i>. στεῖλα, OD. <i>14, 248 ; pf</i>. ἔστολα, GRAMM. (<i>Cram. 4, 369, 9) ; pass. impér. prés. 2 sg. ion</i>. στέλλευ, ANTH. <i>9, 297, 1 ; pl.q.pf. ion. 3 pl</i>. ἐστάλατο, HÉS. <i>Sc. 288 ; vulg</i>. ἐσταλάδατο, HDT. <i>7, 89</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *stel-, disposer.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στελλω - στέλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4725":"<h1>stemma</h1>\n<p>Strong n° 4725 <i>Prononciation [stem'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un filet, une guirlande, posée sur les victimes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στέμμα, ατος (τὸ) :<br>   I</b> couronne, bandeau, bandelette, HDT. <i>1, 132 ; 7, 197 ;</i> THC. <i>4, 133 ;</i> PLAT. <i>Rsp. 393</i> e, <i>617</i> c ; AR. <i>Pl. 39, etc. ; particul. :</i><br><b>      1</b> guirlande de laurier entrelacée autour d’un bâton pour les suppliants, IL. <i>1, 14, 28, 373 ;</i><br><b>      2</b> trame de la vie, EUR. <i>Or. 12 ;</i><br><b>   II</b> <i>à Rome,</i> images des ancêtres, ornées de couronnes, <i>d’où</i> tableau généalogique d’une famille, PLUT. <i>Num. 1</i>.<br><span><b>Étym</b>. στέφω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στεμμα - στέμμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4726":"<h1>stenagmos</h1>\n<p>Strong n° 4726 <i>Prononciation [sten-ag-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un gémissement, un soupir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στεναγμός, οῦ (ὁ)</b> gémissement, PD. <i>fr. 150, 4 ;</i> ESCHL. <i>Pers. 896, etc. ;</i> SOPH. <i>O.R. 30, etc. ;</i> EUR. <i>Or. 959 ;</i> PLAT. <i>Rsp. 578</i> a.<br><span><b>Étym</b>. στενάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στεναγμος - στεναγμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4727":"<h1>stenazo</h1>\n<p>Strong n° 4727 <i>Prononciation [sten-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>soupirer, gémir, murmurer contre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στενάζω</b> <span>(<i>impf</i>. ἐστέναζον, <i>f</i>. στενάξω, <i>ao</i>. ἐστέναξα, <i>pf. inus. ; pass. seul. pf</i>. ἐστέναγμαι)</span><br><b>      1 <i>intr.</i></b> gémir, <i>abs</i>. ESCHL. <i>Pr. 696, etc. ;</i> SOPH. <i>Ph. 916, etc. ;</i> στ. οἰκτρόν, EUR. <i>Suppl. 104,</i> pousser des gémissements lamentables ; μεγάλα στ. EUR. <i>I.T. 957,</i> pousser de grands gémissements ; <i>avec un acc</i>. παιᾶνα στ. EUR. <i>Tr. 578,</i> chanter le péan en gémissant ; στ. ἐπί τινι, SOPH. <i>El. 1299 ;</i> τινί, EUR. <i>Alc. 199, etc</i>. gémir sur qqn <i>ou</i> sur qqe ch. ;<br><b>      2 <i>tr.</i></b> gémir sur, déplorer, <i>acc</i>. SOPH. <i>Ant. 882, etc. ;</i> EUR. <i>I.T. 550, etc. ;</i> DÉM. <i>835, 12</i>.<br><span><b>Étym</b>. στένω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στεναζω - στενάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – gémir, dans un style oriental, hurler d'une façon semi liturgique\n<br><br> – verser des larmes, pleurer silencieusement\n<br><br> – pleurer en y mettant certaines formes, exprimer un grief, chanter un chant funèbre\n<br><br> – pleurer avec cris, pleurer comme un enfant\n<br><br> – exprimer verbalement un grief, se lamenter\n<br><br> – exprimer un grief par des sons inarticulés, ou semi-articulés, gémir</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4728":"<h1>stenos</h1>\n<p>Strong n° 4728 <i>Prononciation [sten-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>qui est étroit, un détroit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>στενός, ή, όν</b>, étroit, resserré :<br><b>   I</b> (<i>avec idée de lieu</i>) THC. <i>7, 51 ;</i> XÉN. <i>Cyn. 5, 30 ;</i> PLAT. <i>Tim. 66</i> a, <i>etc. ; p. opp. à</i> εὐρύς, HDT. <i>2, 8 ;</i> PLAT. <i>Leg. 737</i> a, <i>etc. ; à</i> πλατύς, HDT. <i>4, 195, etc. ; subst</i>. τὸ στενόν, XÉN. <i>Hell. 7, 1, 29 ;</i> τὰ στενά, HDT. <i>7, 223,</i> passage étroit, défilé ; <i>qqf</i>. bras de mer, détroit, THC. <i>2, 86 ;</i> LUC. <i>D. mar. 9, 1 ;</i> ἡ στενή, THC. <i>2, 99,</i> étroite langue de terre ; <i>p. anal. fig. :</i><br><b>      1</b> resserré, gêné : εἰς στενὸν καθίστασθαι, DÉM. <i>15, 24,</i> être réduit aux extrémités, à la détresse ; εἰς στενὸν συνελαύνειν, LUC. <i>Herm. 63,</i> réduire aux extrémités ;<br><b>      2</b> chétif, mesquin, de peu d’importance, PLAT. <i>Gorg. 497</i> c ; POL. <i>7, 7, 6 ;</i> DH. <i>4, 52 ;</i><br><b>      3</b> <i>en parl. du style,</i> maigre, sec, pauvre, ARSTT. <i>Aud. 57 ; Rhet. 3, 12, 2 ;</i><br><b>   II</b> (<i>avec idée de temps</i>) court, de peu de durée, MÉN. <i>4, 194 Meineke ;</i> ALCIPHR. <i>1, 24</i>.<br><span>•<i> Cp</i>. στενώτερος, HPC. <i>V. med. 17 ;</i> PLAT. <i>Tim. 66</i> d ; ARSTT. <i>H.A. 2, 17, 29, etc. ; ou</i> στενότερος (<i>pour</i> *στενϝότερος ; <i>cf</i>. κενός) XÉN. <i>Cyr. 2, 4, 3 ;</i> PLAT. <i>Phæd. 111</i> d. <i>• Sup</i>. στενότατος (<i>pour</i> *στενϝότατος) SCYMN. <i>709</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. στεινός, HDT. HPC. <i>ll. cc. ; cp</i>. στεινότερος, HDT. <i>1, 181 ; 7, 175</i>.<br><span><b>Étym</b>. <i>obscure</i>.</span></span></span><br><br>\n➁ <b>στένος, εος-ους (τὸ)</b> anxiété, détresse, ESCHL. <i>Eum. 520</i>.<br><span><b>Étym</b>. στενός, <i>cf</i>. στεῖνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στενος - στενός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4729":"<h1>stenochoreo</h1>\n<p>Strong n° 4729 <i>Prononciation [sten-okh-o-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être dans un lieu étroit</li>\n<li>rétrécir, comprimer, entraver, réduire au plus étroit\n<ol type=\"a\">\n<li>être douloureusement rétréci en esprit</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στενοχωρέω-ῶ :<br>   I <i>intr.</i></b> être à l’étroit, se trouver gêné, MACH. (ATH. <i>582</i> b) ; <i>fig</i>. être dans l’embarras, HPC. <i>27, 35 ;</i><br><b>   II <i>tr</i>.<br>      1</b> resserrer, rétrécir, CHARIT. <i>5, 3 ; d’où au pass</i>. être à l’étroit, <i>en parl. de pers</i>. ARSTT. <i>Plant. 2, 1, 11 ;</i> DS. <i>20, 29 ;</i> LUC. <i>Tox. 29 ;</i> devenir <i>ou</i> être trop étroit, <i>en parl. d’un lieu,</i> SYN. <i>147</i> a ;<br><b>      2</b> mettre à l’étroit, à la gêne, tourmenter, <i>acc</i>. LUC. <i>Nigr. ;</i><br><b><i>Moy.</i></b> <i>fig</i>. être dans l’anxiété, NT. <i>2Cor. 6, 12, etc</i>.<br><span><b>Étym</b>. στενόχωρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στενοχωρεω - στενοχωρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (4)</li>\n</ul>\n</td></tr>\n</table>","G4730":"<h1>stenochoria</h1>\n<p>Strong n° 4730 <i>Prononciation [sten-okh-o-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étroitesse de place, un lieu étroit</li>\n<li>métaph. affreuse calamité, extrême affliction</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στενοχωρία, ας (ἡ) :<br>   I</b> espace étroit, resserré, THC. <i>2, 89 ; 4, 26 ; 7, 70 ;</i> XÉN. <i>An. 1, 5, 7 ; Hell. 1, 3, 7 ;</i> PLAT. <i>Leg. 708</i> b, <i>Theæt. 195</i> a ; <i>p. opp. à</i> εὐρυχωρία <i>et</i> ἄνεσις, PLUT. <i>M. 679</i> e ; <i>en parl. du temps,</i> courte durée, EL. <i>V.H. 2, 41 ; 3, 23 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> détresse, POL. <i>1, 67, 1 ;</i><br><b>      2</b> anxiété, PLUT. <i>M. 182</i> b ; NT. <i>2Cor. 6, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. στενοχωρίη, HPC. <i>Art. 791</i>.<br><span><b>Étym</b>. στενόχωρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στενοχωρια - στενοχωρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4731":"<h1>stereos</h1>\n<p>Strong n° 4731 <i>Prononciation [ster-eh-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fort, ferme, inébranlable, solide, dur, rigide\n<ol type=\"a\">\n<li>dans un mauvais sens, cruel, rude, têtu, difficile</li>\n<li>dans un bon sens, ferme, constant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στερεός, ά, όν :<br>   I</b> solide, <i>càd. :</i><br><b>      1</b> ferme, dur, IL. <i>17, 493 ;</i> OD. <i>19, 494 ;</i> HDT. <i>1, 52 ;</i> XÉN. <i>Cyn. 9, 16 ; p. opp. à</i> ἀραιός, HPC. <i>Fract. 774 ; à</i> μαλθακός, PLAT. <i>Phædr. 239</i> c, <i>etc. ; subst</i>. ἡ στερεά (<i>s.-e</i>. μερίς) HÉRON, PHIL. BYZ. la partie solide, le cœur (d’une chose) ;<br><b>      2</b> <i>p. suite,</i> robuste, vigoureux, <i>en parl. d’athlètes,</i> DL. <i>2, 132 ; de bras,</i> THCR. <i>Idyl. 22, 48, etc. ;</i><br><b>      3</b> solide, substantiel, <i>en parl. de nourriture,</i> DS. <i>2, 4 ;</i> NT. <i>Hebr. 5, 12, etc. ;</i><br><b>      4</b> <i>en mauv. part :</i> dur, cruel, IL. <i>12, 267 ;</i> OD. <i>23, 103 ;</i> PD. <i>P. 4, 394 ;</i> ESCHL. <i>Pr. 174 ; seul. en poésie ;</i><br><b>      5</b> opiniâtre, obstiné : <i>fig</i>. στ. ἁμάρτημα, SOPH. <i>Ant. 1262,</i> faute produite par l’obstination ;<br><b>      6</b> <i>p. suite,</i> rude, difficile, PLAT. <i>Rsp. 348</i> e ;<br><b>   II</b> <i>t. de géom</i>. solide, cubique, EUCL. <i>Elem. 11, def. 11 ;</i> PLAT. <i>Phil. 51</i> c, <i>Tim. 54</i> e, <i>etc. ; t. d’arithm</i>. cubique, EUCL. <i>Elem. 11, def. 11 ;</i> ARSTT. <i>Pol. 5, 12, 8 ;</i> τὰ στερεά, PLAT. <i>Theæt. 148</i> b, les solides, <i>en gén</i>.<br><span>•<i> Cp</i>. -ώτερος, OD. <i>23, 103 ;</i> PLAT. <i>Rsp. 348</i> e, <i>etc. ;</i> <i>• Sup</i>. -ώτατος, ATT.<br><span><b>Étym</b>. <i>p</i>. *στερεϝός, <i>de la R. indo-europ</i>. *ster-, rigide, fixe ; <i>cf</i>. στερρός, στεῖρα¹ <i>et</i> στεῖρα², <i>lat</i>. sterilis, <i>all</i>. starr.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στερεος - στερεός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4732":"<h1>stereoo</h1>\n<p>Strong n° 4732 <i>Prononciation [ster-eh-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre solide, rendre ferme, fortifier, raffermir\n<ol type=\"a\">\n<li>du corps de quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στερεόω-ῶ :<br>      1</b> rendre ferme <i>ou</i> solide, XÉN. <i>Eq. 4, 3 ; au pass</i>. être solidement établi, SPT. <i>1Reg. 6, 18 ; fig</i>. DS. <i>17, 57 ;</i><br><b>      2</b> fortifier, <i>fig</i>. NT. <i>Ap. 3, 16 ; au pass</i>. devenir fort, XÉN. <i>Cyr. 8, 8, 8 ;</i> NT. <i>Ap. 3, 7</i>.<br><span><b>Étym</b>. στερεός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στερεοω - στερεόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4733":"<h1>stereoma</h1>\n<p>Strong n° 4733 <i>Prononciation [ster-eh'-o-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui a été fait ferme\n<ol type=\"a\">\n<li>le firmament, la voûte du ciel, qui dans les temps anciens étaient considérés comme solides\n<ol>\n<li>une place fortifiée</li>\n</ol>\n</li>\n<li>ce qui fournit un fondement\n<ol>\n<li>sur ce qu'une chose reste fermement, un support</li>\n</ol>\n</li>\n<li>fermeté, constance\n<ol>\n<li>métaph. dans un sens militaire : un front solide</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στερέωμα, ατος (τὸ) :<br>   I</b> toute construction solide, <i>particul. :</i><br><b>      1</b> carène de navire, TH. <i>H.P. 5, 7, 3 ;</i><br><b>      2</b> firmament, SPT. <i>Gen. 1, 6 ; Ezech. 1, 22 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> fondement, appui, <i>particul</i>. le squelette sur lequel repose la constitution du corps, ARSTT. <i>P.A. 2, 9, 12 ;</i><br><b>      2</b> <i>t. de math</i>. τὰ στερεώματα, ANAXAG. (PLUT. <i>M. 891</i> c) ; NÉMÉS. <i>N.H. 5,</i> les corps solides ;<br><b>      3</b> <i>fig</i>. force (d’une armée) SPT. <i>1Macc. 9, 14 ;</i><br><b>      4</b> ratification, SPT. <i>Esth. 9, 29</i>.<br><span><b>Étym</b>. στερεόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στερεωμα - στερέωμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4734":"<h1>Stephanas</h1>\n<p>Strong n° 4734 <i>Prononciation [stef-an-as']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Stéphanas (Angl. Stephanas) = « couronné »\n<ol><li>un chrétien converti de Corinthe</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>Στέφανος, ου (ὁ)</b> <span>[ᾰ]</span> Stéphanos (Étienne) :<br><b>      1</b> Étienne de Byzance, <i>géographe ;</i><br><b>      2</b> <i>autres,</i> DÉM. <i>45, 8, etc. ;</i> LYS. <i>19, 46, etc. Baiter-Sauppe</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Στεφανας - Στεφανᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G4735":"<h1>stephanos</h1>\n<p>Strong n° 4735 <i>Prononciation [stef'-an-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une couronne\n<ol type=\"a\">\n<li>une marque de rang royal ou tout au moins élevé\n<ol>\n<li>la tresse ou guirlande qui était donnée comme prix de la victoire dans les jeux publics</li>\n</ol>\n</li>\n<li>métaph. la bénédiction éternelle qui sera donnée en prix aux véritables serviteurs de Dieu et Christ : la couronne (tresse) qui est la récompense de la justice</li>\n<li>ce qui est l'ornement et l'honneur de certains</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στέφανος, ου (ὁ)</b> <span>[ᾰ]</span> tout ce qui entoure :<br><b>   I</b> <i>en gén. d’où :</i><br><b>      1</b> cercle d’une armée sur le champ de bataille, IL. <i>13, 736 ;</i><br><b>      2</b> enceinte d’une ville, PD. <i>O. 8, 42 ;</i> ANACR. <i>72 ;</i><br><b>      3</b> <i>fig. en parl. d’enfants qui forment comme une couronne autour de qqn,</i> EUR. <i>H.f. 839 ;</i><br><b>   II</b> couronne de feuillage, de fleurs <i>ou</i> de métal, HH. <i>Bacch. 42 ;</i> HÉS. <i>Th. 576 ;</i> PD. <i>I. 7, 72, etc. ; avec le gén. de matière</i> (gazon, olivier, <i>etc</i>.) HDT. <i>8, 26 ; particul. :</i><br><b>      1</b> couronne décernée à un vainqueur, PD. <i>N. 5, 9 ; I. 1, 29, etc. ;</i> στέφανον εἴρειν, PD. <i>N. 7, 113 ;</i> πλέκειν, PD. <i>I. 8, 148, etc. ;</i> ὑφαίνειν, PLUT. <i>M. 646</i> e, tresser une couronne ; στεφάνῳ στεφανοῦν τινα, AR. <i>Av. 1274 ;</i> PLAT. <i>Ion 530</i> d ; <i>ou</i> ἀναδεῖν, THC. <i>4, 121 ;</i> PLUT. <i>Per. 28,</i> ceindre qqn d’une couronne ; στέφανον περιθεῖναι, ESCHL. <i>fr. 190 Dind. ;</i> AR. <i>Eq. 1227 ;</i> περιθέσθαι, SAPPH. <i>fr. 79 Bgk ;</i> EUR. <i>Med. 984 ; fig</i>. honneur, gloire, récompense, SOPH. <i>Aj. 465 ;</i> EUR. <i>Suppl. 315 ;</i> LYCURG. <i>154, 16 ;</i> PLUT. <i>Phil. c. Flam. 3 ; en parl. de pers</i>. HOM. <i>Ep. 13, 1 ;</i> EUR. <i>I.A. 193 ;</i><br><b>      2</b> <i>dans l’Église chrétienne,</i> στέφανοι τοῦ γάμου, NAZ. <i>3, 373 Migne,</i> couronnes nuptiales, <i>que le prêtre posait sur la tête des deux époux, et que le garçon d’honneur</i> (σύντεκνος) <i>tenait au moment de la consécration ;</i><br><b>      3</b> <i>p. anal</i>. Couronne boréale, constellation, ARSTT. <i>Meteor. 2, 5 ;</i> A. RH. <i>3, 1003 ;</i> ARAT. <i>71</i>.<br><span><b>Étym</b>. στέφω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στεφανος - στέφανος</font>\n<br><br>vient apparemment du mot 'stepho' (enrouler ou tresser)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – est une couronne comme insigne de royauté\n<br><br> – comme le Latin « corona » c'est la couronne dans le sens d'un chapelet, tresse ou guirlande – l'insigne de : « la victoire dans les jeux du mérite civique, de la valeur militaire, du bonheur nuptial, de la joie dans la fête ».</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 18 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G4736":"<h1>Stephanos</h1>\n<p>Strong n° 4736 <i>Prononciation [stef'-an-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Etienne (Angl. Stephen) = « couronne »\n<ol><li>un des sept diacres de Jérusalem et premier martyr chrétien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Στέφανος, ου (ὁ)</b> <span>[ᾰ]</span> Stéphanos (Étienne) :<br><b>      1</b> Étienne de Byzance, <i>géographe ;</i><br><b>      2</b> <i>autres,</i> DÉM. <i>45, 8, etc. ;</i> LYS. <i>19, 46, etc. Baiter-Sauppe</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Στεφανος - Στέφανος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (7)</li>\n</ul>\n</td></tr>\n</table>","G4737":"<h1>stephanoo</h1>\n<p>Strong n° 4737 <i>Prononciation [stef-an-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>encercler d'une couronne, couronner : le vainqueur dans une lutte</li>\n<li>orner, honorer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στεφανόω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> conduire autour, diriger en cercle, <i>acc</i>. OPP. <i>C. 4, 90 ; p. suite,</i> ceindre, entourer : πόλιν τείχεσιν, DP. <i>1006,</i> une ville de remparts (<i>v. le moy</i>.) ;<br><b>      2</b> couronner : τινα, EUR. <i>Or. 954,</i> qqn : τινι, EUR. <i>Bacch. 191, etc</i>. de qqe ch. ; τινά τινι, PLAT. <i>Leg. 946</i> b ; τινά τινος, PHILSTR. <i>720,</i> qqn de qqe ch. ; χαίταν, PD. <i>O. 14, 35,</i> couronner la chevelure ; κρᾶτά τινι, EUR. <i>Bacch. 177,</i> couronner la tête de qqe ch. ; <i>avec l’acc. de la chose pour laquelle on couronne :</i> στ. τινα εὐαγγέλια, AR. <i>Eq. 647,</i> couronner qqn pour d’heureuses nouvelles ; offrir sa couronne : πόλιν, DÉM. <i>1343, 1,</i> à une ville ; <i>cf. B. de corr. hell. 1894, p. 13 ;</i> honorer : τινα, EUR. <i>Tr. 1030,</i> qqn ; τινά τινι, PD. <i>O. 1, 162,</i> qqn de qqe ch. ; τύμϐον αἵματι, EUR. <i>Hec. 128,</i> honorer une tombe avec le sang d’une victime ; <i>p. ext</i>. récompenser (avec de l’argent) <i>acc</i>. POL. <i>13, 9, 5 ;</i> PLUT. <i>Tim. 16 ;</i><br><b><i>Moy.</i></b> (<i>surt. aux pf. et pl.q.pf</i>. ἐστεφάνωμαι <i>et</i> ἐστεφανώμην) :<br><b>      1</b> se répandre <i>ou</i> se déployer autour : ἀμφί τινα, IL. <i>15, 153,</i> autour de qqn ; ἐπί τινι, IL. <i>11, 36 ; ou</i> περί τι, IL. <i>5, 739 ;</i> OD. <i>10, 195,</i> autour de qqe ch. ; <i>d’où</i> ceindre, entourer : τι, HÉS. <i>Th. 382,</i> qqe ch. ;<br><b>      2</b> couronner : τινά τινος, D. CHR. <i>1, 291,</i> qqn de qqe ch. ;<br><b>      3</b> se couronner : τινι, SOPH. <i>fr. 480 Dind. ;</i> EUR. <i>Bacch. 106, etc</i>. de qqe ch. ; <i>abs</i>. THC. <i>4, 80 ;</i> XÉN. <i>Hell. 4, 3, 21, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. prés. ion</i>. στεφανεῦμαι, HDT. <i>8, 59 ; fut. moy</i>. στεφανώσομαι <i>au sens act</i>. PHILSTR. <i>V. Ap. 7, p. 294 ; au sens pass</i>. ARSTD. <i>39, 496</i>.<br><span><b>Étym</b>. στέφανος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στεφανοω - στεφανόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Timothée (2)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4738":"<h1>stethos</h1>\n<p>Strong n° 4738 <i>Prononciation [stay'-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la poitrine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στῆθος, εος-ους (τὸ) :<br>   I</b> poitrine, <i>d’où :</i><br><b>      1</b> partie centrale de la poitrine, poitrine de l’homme et de la femme, IL. <i>4, 480 ; 5, 19 ; 8, 326, etc. ; au plur</i>. IL. <i>5, 41 ; 19, 285 ;</i> OD. <i>22, 93 ;</i> poitrail des chevaux, IL. <i>11, 282 ; 12, 204 ;</i> des chiens, XÉN. <i>Cyn. 4, 1 ; particul. :</i> la poitrine comme siège du souffle et de la voix, IL. <i>3, 221 ; 9, 610 ;</i> comme siège du cœur, IL. <i>1, 189 ;</i> OD. <i>1, 341, etc. ;</i><br><b>      2</b> <i>p. suite, fig</i>. la poitrine comme siège des sentiments <i>ou</i> des passions, <i>càd</i>. cœur, âme, <i>au plur</i>. IL. <i>1, 83 ; 2, 142 ; 4, 309, etc. ;</i> OD. <i>3, 18, etc. ;</i> ESCHL. <i>Sept. 563, 865 ; en prose, au sg</i>. PLAT. <i>Phædr. 235</i> c, <i>236</i> c ;<br><b>      3</b> os de la poitrine, sternum, HPC. <i>791</i> h ; poitrine <i>en gén</i>. HPC. <i>24, 5, etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> partie charnue du dedans de la main <i>ou</i> du pied, près des doigts, ARSTT. <i>H.A. 1, 15, 6 ;</i> HPC. <i>276, 9 ; 822</i> c ; <i>1120</i> b ; <i>1153</i> h ; ANTYLL. <i>107 ;</i><br><b>      2</b> sorte de tumeur du foie, ARÉT. <i>Cur. m. acut. 2, 6 ;</i><br><b>      3</b> banc de sable, POL. <i>4, 41, 2</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. pl. poét</i>. στηθέων, ESCHL. <i>ll. cc. ; gén. pl. épq</i>. στήθεσφιν, IL. <i>5, 41 ;</i> OD. <i>22, 93 ; dat. pl. poét</i>. στήθεσσιν, IL. <i>2, 142, etc. ; acc. pl. poét</i>. στήθεα, IL. <i>19, 285, etc. ; dor</i>. στᾶθος, CALL. <i>L. Pall. 88</i>.<br><span><b>Étym</b>. <i>obscure</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στηθος - στῆθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4739":"<h1>steko</h1>\n<p>Strong n° 4739 <i>Prononciation [stay'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>demeurer ferme</li>\n<li>persévérer, persister</li>\n<li>se tenir debout</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στήκω</b>, <i>prés. formé du pf</i>. ἕστηκα (<i>v</i>. ἵστημι) se tenir debout, SPT. <i>3Reg. 8, 11 ;</i> NT. <i>Rom. 14, 4 ; 1Cor. 16, 13 ;</i> A. APHR. <i>Probl. 1, 49</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στηκω - στήκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 7 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (3)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4740":"<h1>sterigmos</h1>\n<p>Strong n° 4740 <i>Prononciation [stay-rig-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ferme condition, constance : d'esprit, stabilité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στηριγμός, οῦ (ὁ)</b> fixité, <i>particul. :</i><br><b>      1</b> station des planètes, DS. <i>1, 81 ;</i> PLUT. <i>M. 76</i> d ;<br><b>      2</b> fermeté, constance, NT. <i>2Petr. 3, 17 ;</i><br><b>      3</b> <i>t. de rhét</i>. appui de la voix sur certaines syllabes, DH. <i>Comp. 20 ; cf</i>. LGN <i>40, 4</i>.<br><span><b>Étym</b>. στηρίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στηριγμος - στηριγμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4741":"<h1>sterizo</h1>\n<p>Strong n° 4741 <i>Prononciation [stay-rid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre stable, placer fermement, fixer</li>\n<li>fortifier, renforcer, rendre ferme</li>\n<li>rendre constant, confirmer son esprit</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στηρίζω</b> <span>(<i>impf</i>. ἐστήριζον, <i>f</i>. στηρίξω, <i>ao</i>. ἐστήριξα, <i>pf. inus. ; pass. f</i>. στηριχθήσομαι, <i>ao</i>. ἐστηρίχθην, <i>pf</i>. ἐστήριγμαι, <i>pl.q.pf</i>. ἐστηρίγμην)</span><br><b>   I <i>tr.</i></b> enfoncer solidement, fixer, appuyer : τι ἔν τινι, IL. <i>11, 28 ; ou</i> κατά τινος, HÉS. <i>Th. 498 ; ou</i> τινί, IL. <i>4, 443,</i> enfoncer <i>ou</i> fixer une ch. dans <i>ou</i> contre une autre ; <i>fig</i>. appuyer, fortifier, affermir, NT. <i>Luc. 22, 32 ; 2Thess. 2, 17 ; au pass</i>. NT. <i>2Petr. 1, 12 ;</i><br><b>   II <i>intr. :</i><br>      1</b> s’appuyer fortement : ποσίν, OD. <i>12, 434,</i> sur ses pieds, <i>d’où</i> s’arrêter fixe ; οὐρανῷ, EUR. <i>Hipp. 1207, ou</i> πρὸς οὐρανόν, EUR. <i>Bacch. 1083 ;</i> PLUT. <i>Syll. 6, litt</i>. s’appuyer contre le ciel, s’élever jusqu’au ciel ; <i>fig</i>. κλέος οὐρανῷ στηρίζον, EUR. <i>Bacch. 972,</i> la gloire qui monte jusqu’au ciel ;<br><b>      2</b> <i>p. suite,</i> se fixer, rester stationnaire, <i>en parl. des corps célestes,</i> PLUT. <i>M. 75</i> d, <i>938</i> a ; PTOL. <i>Tetr. 77 ; p. anal. en parl. d’une maladie,</i> THC. <i>2, 49 ;</i> HPC. <i>1250</i> d, <i>etc. ; fig</i>. persister dans une opinion, <i>avec</i> ἐπί <i>et le gén</i>. DL. <i>2, 136 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. στηρίξομαι, <i>ao</i>. ἐστηριξάμην)</span><br><b>      1</b> s’enfoncer, se fixer : ἐν τῇ κεφαλῇ, ARÉT. <i>p. 1, 30,</i> dans la tête ; <i>p. suite,</i> se fixer, rester stationnaire, <i>en parl. des corps célestes,</i> ARSTT. <i>Mund. 4 ;</i> ARAT. <i>230, 274, etc. ;</i><br><b>      2</b> s’appuyer fortement : πόδεσσιν, IL. <i>21, 242,</i> sur les pieds ; κίοσιν πρὸς οὐρανόν, HÉS. <i>Th. 779,</i> être consolidé par des colonnes qui montent jusqu’au ciel ; <i>fig</i>. κακὸν κακῷ ἐστήρικτο, IL. <i>16, 111,</i> un malheur succédait à un autre (<i>litt</i>. s’appuyait sur un autre).<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. réc</i>. στηρίσω, SPT. <i>Jer. 17, 5, et</i> στηριῶ, SPT. <i>Jer. 24, 6. Ao. réc</i>. ἐστήρισα, ANTH. <i>14, 72 ;</i> APP. <i>Civ. 1, 98</i>.<br><span><b>Étym</b>. <i>cf</i>. στερεός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στηριζω - στηρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 8 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Romains (2)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4742":"<h1>stigma</h1>\n<p>Strong n° 4742 <i>Prononciation [stig'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une marque collée ou tatouée sur le corps. Selon l'usage oriental ancien, les esclaves et soldats portaient le nom ou la marque de leur maître ou commandant tatouée ou incrustée dans leur corps pour indiquer leur appartenance, et il existait certains adorateurs qui se faisaient marquer de la même manière du signe de leurs dieux.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στίγμα, ατος (τὸ) :<br>      1</b> piqûre, ARSTT. <i>H.A. 7, 6, 6 ; particul</i>. piqûre au fer rouge, HDT. <i>7, 233 ; particul</i>. tatouage par suite de pratiques religieuses, HDT. <i>2, 113 ; ou en gén</i>. DS. <i>14, 30 ;</i><br><b>      2</b> tacheture, moucheture, HÉS. <i>Sc. 166 ;</i> DIOSC. <i>2, 98, 205</i>.<br><span><b>Étym</b>. στίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στιγμα - στίγμα</font>\n<br><br>vient de stizo (« rester », c.à.d. piqûre)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4743":"<h1>stigme</h1>\n<p>Strong n° 4743 <i>Prononciation [stig-may']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un instant (c.à.d. un moment) de temps</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στιγμή, ῆς (ἡ) :<br>   I</b> piqûre, <i>marque faite par un instrument pointu,</i> piqûre, point, AL. MYND. (ATH. <i>398</i> d) ; ARSTT. <i>H.A. 6, 3, 2 ; particul. :</i><br><b>      1</b> point mathématique, ARSTT. <i>Top. 1, 18, 8, etc. ;</i><br><b>      2</b> signe de ponctuation ; στ. μέση, GRAMM. <i>758 Bekker, Anecdota græca,</i> point en haut ; στ. τελεία, GRAMM. <i>758 Bekker, Anecdota græca,</i> point final ;<br><b>   II</b> <i>fig</i>. un point, un rien, DÉM. <i>552, 7 ;</i> MÉN. <i>4, 312 Meineke ;</i> στ. χρόνου, PLUT. <i>M. 13</i> d, <i>111</i> c ; NT. <i>Luc. 4, 5, ou simpl</i>. στιγμή, ANTH. <i>7, 472,</i> un instant (<i>cf. lat</i>. punctum temporis).<br><span><b>Étym</b>. στίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στιγμη - στιγμή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4744":"<h1>stilbo</h1>\n<p>Strong n° 4744 <i>Prononciation [stil'-bo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>briller, étinceler, resplendir\n<ol type=\"a\">\n<li>de vêtements</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στίλϐω</b> (<i>seul. prés. impf. et ao. réc</i>. ἔστιλψα) :<br><b>      1 <i>intr.</i></b> briller, resplendir, <i>en parl. de la beauté et de vêtements,</i> IL. <i>3, 392 ; de vêtements,</i> IL. <i>18, 596 ; d’armes,</i> EUR. <i>Andr. 1147 ; de couleurs,</i> PLAT. <i>Phæd. 110</i> d, <i>etc. ; fig</i>. briller de beauté, de grâce, de force, OD. <i>6, 237 ;</i> HH. <i>31, 11 ; 32, 5 ; avec un rég. de m. sign</i>. στ. ἀστραπάς, EUR. <i>Or. 480,</i> briller comme des éclairs <i>en parl. des yeux ;</i><br><b>      2 <i>tr.</i></b> faire briller, rendre brillant, <i>acc</i>. DIOSC. <i>1, 111 ;</i> ARISTÉN. <i>1, 25</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στιλβω - στίλβω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4745":"<h1>stoa</h1>\n<p>Strong n° 4745 <i>Prononciation [sto-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un portique, une colonnade couverte où le peuple pouvait rester ou marcher, protégé du temps et de la chaleur du soleil</li>\n<li>le portique construit par Salomon à la partie orientale du temple (qui ne fut pas détruit lors de la destruction du temple par les Babyloniens). Jésus se promena sous ce portique (<a class=\"ref\" data-r=\"JHN10.23\">Jean 10.23</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στοά, ᾶς (ἡ) :<br>   I</b> portique <i>ou</i> galerie à colonnade, HDT. <i>3, 52 ;</i> XÉN. <i>Hell. 5, 2, 29 ; 7, 3, 41 ; particul. à Athènes :</i><br><b>      1</b> στ. τοῦ βασιλέως, PLAT. <i>Theæt. 210</i> d, <i>Euthyphr. 2</i> a ; DÉM. <i>776, 20, ou</i> βασίλειος, AR. <i>Eccl. 685,</i> le portique où siégeait l’archonte-roi, <i>sur l’agora et, où, p.-ê. étaient affichés les lois ou décrets,</i> AND. <i>1, 85 Baiter-Sauppe ;</i> ISOCR. <i>Areop. 41 ;</i><br><b>      2</b> στ. ποικίλη, DÉM. <i>918, 10 ;</i> ESCHN. <i>80, 5 ;</i> THGNT. (ATH. <i>104</i> b) ; <i>ou simpl</i>. ἡ Ποικίλη (<i>v</i>. ποικίλος) le portique orné de peintures <i>ou</i> Pœcile, <i>où enseignait Zénon, d’où :</i> οἱ ἐκ τῆς στοᾶς, LUC. <i>V. auct. 20, ou</i> ἀπὸ τῆς στοᾶς, PLUT. <i>M. 879</i> a, les philosophes du Portique, <i>càd</i>. les Stoïciens (<i>v</i>. Στωϊκός) ;<br><b>   II</b> <i>p. anal. à cause de la forme des bâtiments :</i><br><b>      1</b> magasin à blé, <i>à Athènes,</i> AR. <i>Ach. 548, Eccl. 686 ;</i><br><b>      2</b> arsenal, ARR. ;<br><b>      3</b> galerie de siège (<i>lat</i>. vinea) : στ. παράλληλος, galerie couverte parallèle au rempart ; στ. ὑπόνομος, galerie secondaire <i>ou</i> transversale, joignant la parallèle au rempart, POL. <i>1, 48, 2, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. στοά (<i>non</i> στοιά) CIA. <i>1, 61, 8 (409 av. J.C.) etc. ; v. Meisterh. p. 44, § 16, 1</i>.<br><span><b>Étym</b>. <i>p</i>. *στωϝ-ιά, <i>indo-europ</i>. *stoh₂-u-ih₂, <i>d’où</i> στοιά <i>et</i> στοά, <i>de la</i> R. *steh₂-, <i>v</i>. ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στοα - στοά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4746":"<h1>stoibas</h1>\n<p>Strong n° 4746 <i>Prononciation [stoy-bas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>branche, grosse branche feuillue</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στιϐάς, άδος (ἡ)</b> <span>[ῐᾰδ]</span><br><b>      1</b> lit d’herbe, de paille <i>ou</i> de feuillage, EUR. <i>Hel. 798, Tr. 507 ;</i> PLAT. <i>Rsp. 372</i> b ; THCR. <i>Idyl. 7, 67 ; particul. pour un bivouac,</i> AR. <i>Pax 348 ;</i> XÉN. <i>Hell. 7, 1, 16 ;</i><br><b>      2</b> <i>en parl. d’animaux,</i> gîte de souris, ARAT. <i>1139 ;</i> nid d’oiseaux, ARSTT. <i>H.A. 8, 29, 3</i>.<br><span><b>Étym</b>. στείϐω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στοιβας - στιβάς</font>\n<br><br>vient du mot steibo (« pas » ou « empreinte »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4747":"<h1>stoicheion</h1>\n<p>Strong n° 4747 <i>Prononciation [stoy-khi'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>toute première chose, de laquelle les autres qui appartiennent à des séries ou composent la totalité prennent leur source, un élément\n<ol type=\"a\">\n<li>les lettres de l'alphabet comme éléments de discours, pas cependant les caractères écrits, mais les sons parlés</li>\n<li>les éléments d'où proviennent toutes choses, le matériau qui créa l'univers</li>\n<li>les corps célestes, soit comme partie des cieux ou parce qu'en eux les éléments de l'homme, vie et destin, sont supposés résider</li>\n<li>les éléments, rudiments, principes primaires et fondamentaux de tout art, science, ou discipline\n<ol>\n<li>c.à.d. de mathématiques, géométrie Euclidienne</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στοιχεῖον, ου (τὸ)</b> <i>litt</i>. ce qui est en rang, ce qui fait partie d’une ligne, <i>p. suite,</i> petit trait aligné, <i>d’où :</i><br><b>   I</b> aiguille qui marque l’ombre sur un cadran solaire, PHILÉM. (<i>Com. fr. 4, 29) ; p. suite,</i> heure, AR. <i>Eccl. 652 ;</i> EUB. <i>3, 261 Meineke ;</i> LUC. <i>Gall. 9, etc. ;</i><br><b>   II</b> caractère d’écriture, lettre, <i>non comme caractère d’écriture distinct ou isolé, mais comme élément constitutif de la syllabe et du mot,</i> ARSTT. <i>Poet. 20, 2 ;</i> τὸ ῥῶ τὸ στοιχεῖον, PLAT. <i>Crat. 426</i> d, la lettre ῥ ; γραμμάτων στοιχεῖα, PLAT. <i>Theæt. 202</i> e, lettres de l’écriture ; κατὰ στοιχεῖον, ANTH. <i>11, 15, 3 ;</i> PLUT. <i>M. 422</i> e, par ordre alphabétique ;<br><b>   III</b> <i>p. suite,</i> élément, principe d’une chose, XÉN. <i>Mem. 2, 1, 1 ;</i> PLAT. <i>Leg. 790</i> c, <i>etc. ;</i> PLUT. <i>M. 12</i> c, <i>1069</i> f, <i>etc. ; d’où</i> point de départ, <i>p. opp. à</i> πέρας, ARSTT. <i>Pol. 1, 9 ; particul. :</i><br><b>      1</b> <i>t. de philos.,</i> éléments de l’univers, PLAT. <i>Theæt. 201, etc. ;</i> ARSTT. <i>P.A. 2, 1, etc. ;</i> PLUT. <i>M. 63</i> c, <i>etc. ;</i> στοιχεῖα ἀμφότερα, POLÉM. <i>1, 11,</i> les deux éléments, la terre et l’eau ;<br><b>      2</b> éléments d’une science, de la géométrie (les points, les lignes, <i>etc</i>.) PLUT. <i>M. 877</i> e, <i>980</i> a ; de la logique ; ARSTT. <i>Rhet. 2, 22 ; particul</i>. les idées fondamentales, ARSTT. <i>Rhet. 1, 2 ;</i> de la grammaire (les noms, les verbes) GRAMM. ; DH. <i>Comp. 2, etc. ; t. de rhét</i>. les points principaux (πρόσωπα, πράγματα, τρόποι, καιροί, <i>etc</i>.) auxquels on se reporte dans une démonstration, DH. <i>Lys. 15 ;</i> points principaux d’une description, MÉN. RHÉT. <i>9, 167 W. ;</i> points principaux dans la construction et l’agencement des mots, DH. <i>Comp. 6, 42 ;</i><br><b>      3</b> <i>t. d’astr</i>. les planètes, MAN. <i>4, 624 ; ou chez les Alexandrins,</i> signes du zodiaque, <i>réputés comme les principes de la vie pour les hommes,</i> DL. <i>6, 102</i>.<br><span><b>Étym</b>. στοῖχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στοιχειον - στοιχεῖον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Galates (2)</li>\n<li>Colossiens (2)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G4748":"<h1>stoicheo</h1>\n<p>Strong n° 4748 <i>Prononciation [stoy-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avancer en rang comme la marche d'un soldat, aller en ordre\n<ol type=\"a\">\n<li>métaph. aller en prospérant, bien se conduire</li>\n</ol>\n</li>\n<li>marcher\n<ol type=\"a\">\n<li>diriger sa vie, vivre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στοιχέω-ῶ :<br>      1</b> être aligné <i>ou</i> marcher en rang, XÉN. <i>Cyr. 6, 3, 34 ; en gén</i>. être aligné, <i>en parl. de feuilles,</i> TH. <i>H.P. 3, 18, 5, etc. ; d’où</i> former une ligne, ALC. <i>11 Ahrens ;</i><br><b>      2</b> <i>p. suite,</i> marcher à la file, à la suite de, suivre, <i>dat</i>. NT. <i>Rom. 4, 12 ; fig</i>. se conformer à, <i>dat</i>. POL. <i>28, 5, 6 ;</i> DH. <i>6, 65 ;</i> NT. <i>Gal. 5, 25, etc. ; abs</i>. NT. <i>Ap. 21, 24</i>.<br><span><b>Étym</b>. στοῖχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στοιχεω - στοιχέω</font>\n<br><br>vient d'un dérivé de steicho (ranger en lignes régulières)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Galates (2)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4749":"<h1>stole</h1>\n<p>Strong n° 4749 <i>Prononciation [stol-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un équipement</li>\n<li>un équipement en vêtements, habillement, une robe\n<ol type=\"a\">\n<li>spéc. un large vêtement pour hommes allant jusqu'aux pieds, porté par les rois, les sacrificateurs et personnes de haut rang.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στολή, ῆς (ἡ) :<br>   I</b> équipement, ajustement, <i>d’où :</i><br><b>      1</b> habillement, vêtement, HDT. <i>1, 88 ; 4, 78 ;</i> ESCHL. <i>Pers. 192 ;</i> EUR. <i>Rhes. 313 ;</i> AR. <i>Eccl. 846, etc. ;</i> XÉN. <i>Cyr. 8, 1, 40, etc. ; particul</i>. robe, SOPH. <i>O.C. 1357, etc. ;</i> peau de lion, EUR. <i>H.f. 465, etc. ; en parl. des plumes qui recouvrent le corps des oiseaux,</i> A. TAT. <i>1, 15 ;</i><br><b>      2</b> <i>p. suite,</i> armement, ESCHL. <i>Suppl. 764 ;</i><br><b>   II</b> armée, ESCHL. <i>Pers. 1018</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. σπόλα, SAPPH. <i>fr. 55 Bgk</i>.<br><span><b>Étym</b>. στέλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στολη - στολή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G4750":"<h1>stoma</h1>\n<p>Strong n° 4750 <i>Prononciation [stom'-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la bouche, comme partie du corps, de l'homme, des animaux, des poissons, etc.\n<ol type=\"a\">\n<li>les pensées de l'âme d'un homme peuvent s'exprimer verbalement par sa bouche, et donc le « cœur » ou « l'âme » et la bouche sont des mots très distincts</li>\n</ol>\n</li>\n<li>le tranchant d'une épée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στόμα, ατος (τὸ) :<br>A</b> bouche :<br><b>   I</b> la bouche, <i>partie du corps, chez l’homme,</i> OD. <i>11, 425 ;</i> XÉN. <i>Mem. 2, 6, 32, etc. ; au plur. au sens du sg</i>. SOPH. <i>Tr. 938 ;</i> A. RH. <i>4, 1607 ;</i> NIC. <i>Al. 210, etc. ; et chez les animaux,</i> HÉS. <i>Sc. 146, 389 ;</i> ESCHL. <i>Pers. 193 ;</i> SOPH. <i>Ph. 1156 ;</i> XÉN. <i>Eq. 6, 9, etc. ; p. ext</i>. face, visage : ἐξεκυλίσθη ἐπὶ στόμα, IL. <i>6, 43,</i> il roula tombant sur la face ; πεσεῖν ἐπὶ στόμα, PLUT. <i>Demetr. 29, etc</i>. tomber sur la face ; ἐπὶ στόμα ὠθεῖν, IL. <i>16, 410,</i> faire tomber qqn sur la face ; κατὰ στόμα, ESCHL. <i>Ch. 573 ;</i> κατὰ τὸ στόμα, PLAT. <i>Leg. 855</i> d, en face ; <i>p. anal. :</i><br><b>      1</b> face, front d’une armée, XÉN. <i>An. 3, 4, 43, etc. ; p. opp. à</i> οὐρά, XÉN. <i>An. 3, 4, 42, etc. ;</i> κατὰ στόμα, HDT. <i>8, 11 ;</i> EUR. <i>Rhes. 491,</i> en face, de front ; <i>p. opp. à</i> ἐν δεξιᾷ <i>et</i> ἐν ἀριστερᾷ, XÉN. <i>An. 5, 2, 26 ;</i><br><b>      2</b> <i>en parl. d’une arme,</i> pointe, IL. <i>15, 389 ;</i> ATHÉNÉE MÉC. <i>24, 2 ; ou</i> tranchant, PHILSTR. <i>732 ;</i> NT. <i>Luc. 21, 24, etc. ;</i><br><b>   II</b> la bouche comme organe de l’alimentation : τι ἐς τὸ στόμα λαμϐάνειν, XÉN. <i>Mem. 3, 14, 5,</i> porter qqe ch. (des aliments) à sa bouche ; κορέσαι στόμα, SOPH. <i>Ph. 1156, litt</i>. rassasier sa bouche ; <i>fig</i>. ce qui sert à engloutir, à dévorer, gouffre : πόντιον, EUR. <i>Rhes. 436,</i> gouffre de la mer ; πολέμοιο, IL. <i>10, 8 ; ou</i> ὑσμίνης, IL. <i>20, 359,</i> gouffre de la guerre, du combat (<i>càd. l’endroit où la guerre, où le combat dévorent le plus de victimes</i>) ;<br><b>   III</b> la bouche comme organe de la parole, IL. <i>2, 489 ;</i> PD. <i>N. 10, 35 ; Att. en gén., etc. :</i> στόμα οἴγειν, ESCHL. <i>Pr. 612,</i> ouvrir la bouche ; λύειν, EUR. <i>Hipp. 1060 ;</i> ISOCR. <i>252</i> c, délier la bouche ; κινεῖν, SOPH. <i>O.C. 1277,</i> mettre la bouche en mouvement ; διαίρειν, DÉM. <i>375, 14,</i> ouvrir la bouche ; κλῄειν, EUR. <i>Ph. 865, ou</i> συγκλῄειν, AR. <i>Th. 40,</i> fermer la bouche ; κοιμᾶν, ESCHL. <i>Ag. 1247,</i> laisser reposer sa bouche ; σῖγα ἔχειν, EUR. <i>Hipp. 660, etc</i>. tenir sa bouche silencieuse ; δάκνειν, ESCHL. <i>fr. 293 ;</i> SOPH. <i>Tr. 977,</i> se mordre la bouche pour ne pas parler ; ἀπὸ στόματος εἰπεῖν, XÉN. <i>Mem. 3, 6, 9, etc. ;</i> PLAT. <i>Theæt. 142</i> d ; PLUT. <i>Sol. 8, etc. ; ou</i> ἐν στόματι λέγειν, AR. <i>Ach. 198,</i> parler de bouche, de mémoire ; διὰ στόματος ἔχειν, XÉN. <i>Cyr. 1, 4, 25 ;</i> PLUT. <i>Fab. 26, M. 697</i> c, <i>etc. ; ou</i> ἀνὰ στόμα ἔχειν, EUR. <i>Andr. 95 ; ou</i> διὰ στόμα ἔχειν, AR. <i>Lys. 855 ; ou</i> διὰ στόμα ἄγεσθαι, IL. <i>14, 91 ; ou</i> ἐν στόματι ἔχειν, IL. <i>2, 250,</i> avoir sans cesse à la bouche ; διὰ στόματος εἶναι <i>ou</i> γίγνεσθαι, THCR. <i>Idyl. 12, 21 ;</i> ARSTT. (PLUT. <i>M. 115</i> c) ; LUC. <i>Lex. 23 ; au plur</i>. διὰ στομάτων ἔρχεσθαι, THGN. <i>18 ; cf</i>. PLAT. <i>Rsp. 463</i> e, <i>etc</i>. venir sans cesse sur les lèvres, <i>en parl. d’une parole, d’un propos, etc. ;</i> ἐν στόμασι κεῖσθαι, THGN. <i>240,</i> être dans toutes les bouches ; ἐλθεῖν ἐπὶ στόμα, ESCHL. <i>fr. 326 ;</i> PLAT. <i>Rsp. 563</i> c, venir à la bouche, <i>en parl. d’une pensée, d’une parole ;</i> ἐξ ἑνὸς στόματος, AR. <i>Eq. 670 ;</i> PLAT. <i>Rsp. 364</i> a, <i>etc. ; ou</i> ἀφ' ἑνὸς στόματος, ANTH. <i>11, 159 ; ou</i> ἐν ἑνὶ στόματι, NT. <i>Rom. 15, 6,</i> d’une seule voix ; <i>p. suite,</i> parole, langage, SOPH. <i>O.R. 426, 706 ; O.C. 671 ; fr. 669 Dind. ;</i> EUR. <i>Or. 592 ;</i> THCR. <i>Idyl. 8, 81, etc. ;</i> στόμα ἀνόσιον, SOPH. <i>O.C. 981,</i> langage impie ; στόμα θεῖον, SOPH. <i>O.C. 603,</i> bouche <i>ou</i> voix des dieux, oracle ;<br><b>B</b> <i>p. anal</i>. embouchure d’un fleuve, IL. <i>12, 24 ;</i> OD. <i>5, 441 ;</i> ESCHL. <i>Pr. 846 ;</i> HDT. <i>1, 202, etc. ;</i> THC. <i>4, 102 ;</i> XÉN. <i>An. 6, 2, 1, etc. ;</i> de la mer, PD. <i>P. 4, 302 ;</i> HDT. <i>4, 85 ;</i> THC. <i>4, 75 ;</i> XÉN. <i>An. 6, 4, 1, etc. ; p. ext</i>. orifice, ouverture, entrée (d’un port, OD. <i>10, 90 ;</i> THC. <i>7, 5, 6, etc. ;</i> XÉN. <i>Hell. 1, 5, 15, etc. ;</i> d’un golfe, THC. <i>4, 49 ;</i> d’une ville, SOPH. <i>Ant. 119 ;</i> d’une rue, XÉN. <i>Cyr. 2, 4, 4 ;</i> d’une maison, XÉN. <i>An. 4, 5, 25 ;</i> d’un organe (matrice, HPC. <i>604, 24, etc. ;</i> estomac, NIC. <i>Al. 20, etc</i>.)) ; <i>p. suite,</i> bord d’un rempart, EUR. <i>Ph. 1166, etc. ; fig</i>. στ. τοῦ βίου, XÉN. <i>11, 1,</i> terme de la vie.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. στύμα, THCR. <i>Idyl. 29, 25</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *steh₃-mn-, bouche ; <i>cf. zend</i> staman, bouche <i>d’un chien ; v</i>. στόμαχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στομα - στόμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n78 fois dans 71 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Luc (9)</li>\n<li>Jean (1)</li>\n<li>Actes (12)</li>\n<li>Romains (6)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n<li>2 Jean (2)</li>\n<li>3 Jean (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (22)</li>\n</ul>\n</td></tr>\n</table>","G4751":"<h1>stomachos</h1>\n<p>Strong n° 4751 <i>Prononciation [stom'-akh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la gorge</li>\n<li>une ouverture, un orifice, spéc. l'estomac</li>\n<li>l'estomac</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στόμαχος, ου (ὁ)</b> <span>[ᾰ]</span> <i>litt</i>. orifice, ouverture, <i>d’où :</i><br><b>      1</b> gorge, IL. <i>3, 292 ; 17, 47 ; particul</i>. le derrière du cou, ARSTT. <i>H.A. 1, 12 ;</i><br><b>      2</b> orifice de l’estomac, NIC. <i>Al. 22 ;</i> PLUT. <i>M. 687</i> d ; <i>d’où</i> estomac, PLUT. <i>M. 698</i> a, <i>etc. ;</i><br><b>      3</b> orifice de certains organes (col de la vessie, <i>etc</i>. HPC. <i>Aër. 286 ;</i> de l’utérus, HPC. <i>598, 45, etc</i>.).<br><span><b>Étym</b>. στόμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στομαχος - στόμαχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4752":"<h1>strateia</h1>\n<p>Strong n° 4752 <i>Prononciation [strat-i'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une expédition, une campagne, un service militaire, un combat</li>\n<li>métaph. Paul compare sa lutte avec les difficultés qui s'opposent à lui dans l'accomplissement de ses devoirs apostoliques, à un combat</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρατεία, ας (ἡ)</b> <span>[ᾰτ]</span><br><b>   I</b> expédition militaire (sur terre et sur mer) : ἐπί τινα, HDT. <i>5, 77,</i> contre qqn ; στρατείαν ποιεῖσθαι, HDT. <i>1, 71, 171 ;</i> THC. <i>1, 15, etc. ;</i> XÉN. <i>Hell. 7, 4, 19, etc. ;</i> στρατεύειν, EUR. <i>Suppl. 116, etc. ;</i> στρατεύεσθαι, DÉM. <i>545, 15, etc</i>. faire une expédition ; ἐπὶ στρατείας εἶναι, PLAT. <i>Rsp. 468</i> b ; AND. <i>21, 29 ; ou</i> ἐν στρατείᾳ εἶναι, XÉN. <i>Cyr. 5, 2, 19,</i> être en campagne ;<br><b>   II</b> <i>p. suite :</i><br><b>      1</b> service militaire, <i>au pl</i>. PLAT. <i>Rsp. 404</i> a ; <i>Leg. 878</i> c ; DÉM. <i>568, 9 ;</i><br><b>      2</b> discipline militaire, DC. <i>78, 36 ;</i><br><b>      3</b> fonctions militaires, <i>particul</i>. commandement militaire, DC. <i>72, 12 au pl. ;</i><br><b>   III</b> troupes en campagne, EUR. <i>I.A. 495, Rhes. 263</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. στρατηΐη, HDT. <i>ll. cc. Dans les inscr. att. l’écriture flotte entre</i> στρατεία <i>et</i> στρατιά <i>au sens de</i> « expédition » ; <i>au sens de</i> « troupes », on trouve <i>seul</i>. στρατιά, <i>v. Meisterh. p. 43, 29</i>.<br><span><b>Étym</b>. στρατός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατεια - στρατεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4753":"<h1>strateuma</h1>\n<p>Strong n° 4753 <i>Prononciation [strat'-yoo-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une armée</li>\n<li>une bande de soldats</li>\n<li>corps de garde, hommes de garde</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στράτευμα, ατος (τὸ)</b> <span>[ᾰτ]</span><br><b>      1</b> expédition, campagne, HDT. <i>3, 48, 49 ; 8, 112 ; 9, 33 ;</i> ESCHL. <i>Pers. 758 ;</i> EUR. <i>Cycl. 283 ; au plur</i>. AR. <i>Lys. 1133 ;</i><br><b>      2</b> troupes, armée en campagne, HDT. <i>1, 6 ; 7, 48 ;</i> ESCHL. <i>Pers. 469 ;</i> XÉN. <i>Cyr. 3, 3, 26, etc. ; à Rome,</i> légion, DC. <i>38, 47 ; en parl. de forces navales,</i> THC. <i>6, 74 ;</i> SOPH. <i>Ph. 59 ; p. ext</i>. foule, peuple, EUR. <i>Suppl. 653</i>.<br><span><b>Étym</b>. στρατεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατευμα - στράτευμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G4754":"<h1>strateuomai</h1>\n<p>Strong n° 4754 <i>Prononciation [strat-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire une expédition militaire, conduire des soldats à la guerre ou la bataille, (se dit d'un commandant)</li>\n<li>remplir ses devoirs militaires, être en service actif, être un soldat</li>\n<li>combattre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρατεύω</b> <span>[ᾰ]</span> <span>(<i>f</i>. εύσω, <i>ao</i>. ἐστράτευσα, <i>pf</i>. ἐστράτευκα, <i>pf. pass</i>. ἐστράτευμαι)</span><br><b>      1</b> servir comme soldat, XÉN. <i>Cyr. 4, 4, 11 ; Hell. 7, 4, 34, etc. ;</i> PLAT. <i>Leg. 943</i> a, <i>etc. ; p. suite,</i> faire campagne, faire une expédition (sur terre <i>ou</i> sur mer, comme chef <i>ou</i> comme soldat) ATT. ; ἐπί τινα, HDT. <i>1, 77 ;</i> THC. <i>3, 7 ;</i> ἐπὶ Μίλητον, HDT. <i>6, 7 ;</i> ἐπὶ Τροίαν, THC. <i>1, 8 etc</i>. contre qqn, contre Milet, contre Troie ; εἰς Πλάταιαν, THC. <i>2, 6, etc. ;</i> πρὸς Ἄϐυδον, XÉN. <i>Hell. 1, 2, 15,</i> à Platée, contre Abydos ; στρατείαν, EUR. <i>Suppl. 116, etc. ;</i> πόλεμον, THC. <i>1, 112,</i> diriger une expédition, une guerre au dehors ;<br><b>      2</b> <i>postér</i>. enrôler des soldats, <i>acc</i>. HDN <i>2, 14, 12 ;</i> APP. <i>Civ. 1, 42, etc. ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. στρατεύσομαι, <i>ao</i>. ἐστρατευσάμην, <i>rar</i>. ἐστρατεύθην)</span> servir comme soldat. HDT. <i>1, 209 ; 7, 61 ;</i> AR. <i>Ran. 1113 ;</i> LYS. <i>114, 33, etc. ;</i> στρ. ψιλόν, AR. <i>Th. 232 ;</i> ὁπλίτην, XÉN. <i>Mem. 3, 4, 1,</i> servir comme soldat d’infanterie légère, comme hoplite ; στρ. μισθοῦ, XÉN. <i>Cyr. 3, 2, 7,</i> servir pour une solde, <i>càd</i>. comme mercenaire ; ὑπό τινι, PLUT. <i>Cam. 2,</i> servir sous qqn ; ἐπί τινα, HDT. <i>1, 71, etc. ;</i> XÉN. <i>An. 2, 1, 1, etc</i>. contre qqn ; εἰς τὴν Ἀσίαν, XÉN. <i>Hell. 3, 4, 2,</i> faire campagne en Asie ; σύν τινι, XÉN. <i>Cyr. 5, 4, 37, etc. ;</i> μετά τινος, EUR. <i>I.A. 967 ;</i> XÉN. <i>Hell. 4, 6, 3,</i> conjointement avec qqn ; ὑπέρ τινος, pour protéger qqn <i>ou</i> qqe ch. PLAT. <i>Rsp. 429</i> b ; <i>ou</i> à la place de qqn, PLAT. <i>Leg. 878</i> d, <i>etc. ;</i> στρ. ἔξω, PLAT. <i>Leg. 814</i> a, faire campagne au dehors, hors du pays.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass. au sens moy</i>. ἐστρατεύθην, PD. <i>P. 1, 51 ;</i> APD. <i>1, 9, 13, 2. Dans les inscr. att</i>. στρατεύειν <i>dans une inscr. du 6<sup>e</sup> siècle av. J.C. ;</i> στρατεύεσθαι <i>dans les inscr. des 4<sup>e</sup> et 3<sup>e</sup> siècles ; v. Meisterh. p. 154, § 75, 2</i>.<br><span><b>Étym</b>. στρατός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατευομαι - στρατεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 7 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4755":"<h1>strategos</h1>\n<p>Strong n° 4755 <i>Prononciation [strat-ay-gos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le commandant d'une armée, général, stratège</li>\n<li>dans le N.T. un commandant civil, un gouverneur\n<ol type=\"a\">\n<li>le nom du plus haut magistrat dans les colonies; ils avaient le pouvoir d'administrer la justice pour les cas importants</li>\n<li>des magistrats civils</li>\n</ol>\n</li>\n<li>commandant du temple, c.à.d. le commandant des Lévites qui montaient la garde dans et autour du temple</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρατ·ηγός, οῦ (ὁ)</b> <span>[ᾰ]</span><br><b>   I</b> chef d’armée, général, ESCHL. <i>Ag. 581, etc. ;</i> SOPH. <i>Ant. 8, etc. ;</i> XÉN. <i>Mem. 3, 1, 3, etc. ;</i> στρ. ἀνήρ, ESCHL. <i>Ag. 1626 ;</i> XÉN. <i>Ages. 3, 5, m. sign. ; avec un gén</i>. στρ. στρατοῦ, HDT. <i>7, 83 ;</i> στρατιᾶς, XÉN. <i>An. 1, 7, 12, etc</i>. général d’une armée, chef d’une expédition ; στρ. ὅλων, SOPH. <i>Aj. 1106 ;</i> τῶν πάντων, XÉN. <i>Hell. 3, 2, 13,</i> généralissime ; <i>fig</i>. PLAT. <i>Theæt. 153</i> a, <i>Conv. 193</i> b, <i>etc. ; comiq. au fém</i>. ἡ στρ. AR. <i>Eccl. 491, 500 ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> <i>à Athènes,</i> stratège, <i>sorte de ministre de la guerre, préposé à l’entretien des troupes de terre et de mer avec un droit de juridiction pour toutes les questions se rattachant à l’administration de la guerre (exercice du commandement, recrutement des troupes, jugement des crimes ou délits militaires ; contrôle des impôts de guerre, administration de la caisse de l’armée ; sécurité du pays, etc.) ; à l’origine, les stratèges étaient au nombre de dix, un par tribu, choisis tous les ans parmi les citoyens d’Athènes, et exerçant le commandement à tour de rôle ; au temps de Démosthène, les stratèges commandant en temps de guerre étaient au nombre de deux, le commandant des troupes d’infanterie</i> (ὁ ἐπὶ τῶν ὅπλων <i>ou</i> ὁπλιτῶν, DÉM. <i>238, 13 ; 265, 7, 19, etc.) et le commandant des troupes de cavalerie</i> (ὁ ἐπὶ τῶν ἱππέων, DÉM. <i>265, 20) ; les autres restaient à Athènes,</i> DÉM. <i>47, 14 ;</i><br><b>      2</b> stratège, <i>chef militaire et civil des ligues achéenne et étolienne,</i> POL. <i>2, 43, 1 ;</i> STR. <i>385 ;</i><br><b>      3</b> haut fonctionnaire dans les villes d’Asie Mineure, HDT. <i>5, 38 ;</i><br><b>      4</b> <i>à Rome,</i> consul, POL. <i>1, 7, 12, etc. ; joint à</i> ὕπατος, POL. <i>1, 52, 5, etc. ;</i> PLUT. <i>Flam. 10 ; ou</i> préteur, POL. <i>3, 106, 6 ;</i> ARR. <i>Epict. 2, 1, 26 ;</i> préteur urbain, POL. <i>33, 1, 5 ;</i><br><b>      5</b> magistrat dans les colonies romaines, NT. <i>Ap. 16, 20 ;</i> ATH. <i>37</i> c ;<br><b>      6</b> officier préposé à la garde du temple à Jérusalem, NT. <i>Luc. 22, 52 ; Ap. 4, 1, etc. ;</i><br><b>      7</b> préfet de police <i>en Égypte,</i> STR. <i>797</i>.<br><span><b>Étym</b>. στρατός, ἄγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατηγος - στρατηγός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (8)</li>\n</ul>\n</td></tr>\n</table>","G4756":"<h1>stratia</h1>\n<p>Strong n° 4756 <i>Prononciation [strat-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une armée, une bande de soldats</li>\n<li>dans le N.T., les armées des cieux\n<ol type=\"a\">\n<li>les troupes d'anges</li>\n<li>les corps célestes, étoiles du ciel (appelées armées à cause de leur nombre et de leur alignement)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρατιά, ᾶς (ἡ)</b> <span>[ᾰ]</span><br><b>   I</b> armée, troupe militaire, <i>d’où :</i><br><b>      1</b> armée, PD. <i>O. 6, 28 ;</i> ESCHL. <i>Pers. 534, etc. ;</i> THC. <i>6, 33, etc. ; particul</i>. armée de terre, <i>par opp. à</i> armée de mer, HDT. <i>6, 12, etc. ;</i><br><b>      2</b> troupe, <i>en gén</i>. PD. <i>P. 11, 75 ; N. 11, 45 ; fig. en parl. de choses :</i> ἡ στρ. τοῦ οὐρανοῦ <i>ou</i> αἱ στρ. τῶν οὐρανῶν, SPT. <i>2Par. 3, 3 ; Neh. 9, 6 ; Soph. 1, 5,</i> l’armée des cieux, les corps célestes, <i>hébraïsme ;</i><br><b>   II</b> expédition militaire, AR. <i>Eq. 587, Th. 828, etc. ;</i> THC. <i>8, 108, etc. ;</i><br><b>   III</b> service militaire, AR. <i>Ach. 1143</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. στρατιή, HDT. <i>l. c. etc</i>.<br><span><b>Étym</b>. στρατός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατια - στρατιά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4757":"<h1>stratiotes</h1>\n<p>Strong n° 4757 <i>Prononciation [strat-ee-o'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un soldat (ordinaire)</li>\n<li>métaph. un champion de la cause de Christ</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρατιώτης, ου (ὁ)</b> <span>[ᾰ]</span><br><b>   I</b> soldat, <i>primit</i>. tout homme enrôlé pour le service militaire, HDT. <i>4, 134 ;</i> ATT. (AR. <i>Ach. 1065, etc.) dans les discours :</i> ἄνδρες στρατιῶται, THC. <i>7, 61,</i> soldats ! <i>postér</i>. soldat de profession, ARSTT. <i>Nic. 3, 8, 9 ; particul</i>. soldat servant sur un navire, THC. <i>2, 88 ; au sg. en un sens collectif,</i> THC. <i>6, 24 ;</i><br><b>   II</b> <i>n. de plantes :</i><br><b>      1</b> στρ. ποτάμιος, DIOSC. <i>4, 102,</i> sorte de plante aquatique ;<br><b>      2</b> στρ. χιλιόφυλλος, DIOSC. <i>4, 103,</i> achillée <i>ou</i> millefeuille (<i>achillea millefolium ou tomentosa</i> L.).<br><span><b>Étym</b>. στρατιά.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατιωτης - στρατιώτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n26 fois dans 24 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (6)</li>\n<li>Actes (13)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4758":"<h1>stratologeo</h1>\n<p>Strong n° 4758 <i>Prononciation [strat-ol-og-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rassembler (rassembler) une armée, enrôler des soldats</li>\n<li>du commandant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρατο·λογέω-ῶ</b> <span>[ᾰ]</span> enrôler des soldats, DH. <i>11, 24 ; au pass</i>. DS. <i>12, 67 ;</i> PLUT. <i>Cæs. 35</i>.<br><span><b>Étym</b>. στρ. -λογος <i>de</i> λέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατολογεω - στρατολογέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4759":"<h1>stratopedarches</h1>\n<p>Strong n° 4759 <i>Prononciation [strat-op-ed-ar'-khace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le commandant d'un camp et d'une armée, un tribun militaire</li>\n<li>préfet Prétorien, commandant des cohortes prétoriennes, capitaine du corps de garde de l'empereur romain</li>\n</td>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρατοπεδ·άρχης, ου (ὁ)</b> <span>[ᾰ]</span><br><b>      1</b> commandant d’une armée, JOS. <i>B.J. 2, 19, 4 ;</i> LUC. <i>H. conscr. 22, etc. ;</i><br><b>      2</b> tribun d’une légion, DH. <i>10, 36</i>.<br><span><b>Étym</b>. στρατόπεδον, ἄρχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατοπεδαρχης - στρατοπεδάρχης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>","G4760":"<h1>stratopedon</h1>\n<p>Strong n° 4760 <i>Prononciation [strat-op'-ed-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un camp militaire</li>\n<li>des soldats dans un camp, une armée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρατό·πεδον, ου (τὸ)</b> <span>[ᾰ]</span><br><b>   I</b> le sol sur lequel campe une armée, campement, camp, HDT. <i>4, 114 ;</i> ESCHL. <i>Sept. 79 ;</i> EUR. <i>Rhes. 522 ;</i> ATT. ;<br><b>   II</b> troupe campée, armée dans un camp, HDT. <i>1, 76 ; 5, 113 ; 9, 51, etc. ;</i> SOPH. <i>Ph. 10, etc. ; d’où</i> armée, <i>en gén. ; p. anal</i>. flotte, HDT. <i>8, 81, 94 ;</i> THC. <i>1, 117 ;</i> XÉN. <i>Hell. 6, 3, 18 ; particul. :</i><br><b>      1</b> <i>à Rome,</i> la légion, POL. <i>1, 16, 2 ;</i> DC. <i>38, 47 ; 55, 23 etc. ;</i><br><b>      2</b> troupe, <i>en gén</i>. PLAT. <i>Rsp. 568</i> d.<br><span><b>Étym</b>. στρατός, πέδον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρατοπεδον - στρατόπεδον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4761":"<h1>strebloo</h1>\n<p>Strong n° 4761 <i>Prononciation [streb-lo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tordre, tourner de travers</li>\n<li>torturer, mettre au chevalet de torture</li>\n<li>métaph. pervertir, de quelqu'un qui tord ou torture le langage dans un faux sens</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρεϐλόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἐστρέϐλωσα, <i>pf. inus. ; pass. ao</i>. ἐστρεϐλώθην, <i>pf</i>. ἐστρέϐλωμαι)</span> tordre :<br><b>   I</b> <i>au propre :</i><br><b>      1</b> <i>en gén</i>. tordre (un câble, une corde d’instrument, <i>etc</i>.) HDT. <i>7, 36 ;</i> PLAT. <i>Rsp. 531</i> b ;<br><b>      2</b> tordre sur un chevalet, sur un instrument de supplice, torturer, AR. <i>Nub. 620, etc. ;</i> ANT. <i>133, 17 ; au pass</i>. AR. <i>Pl. 875, etc. ;</i> LYS. <i>134, 40 ;</i> PLAT. <i>Rsp. 361</i> e ;<br><b>      3</b> tordre un membre déboîté pour le rajuster, HDT. <i>3, 129, etc. ;</i><br><b>      4</b> <i>au pass</i>. être tordu, <i>d’où en parl. des yeux,</i> être louche, A. APHR. ;<br><b>   II</b> <i>fig</i>. tordre, <i>d’où</i> faire dévier, pervertir (le sens d’un écrit) NT. <i>2Petr. 2, 16 ; au pass</i>. SPT. <i>2Reg. 22, 27</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy. au sens pass</i>. στρεϐλώσομαι, PLAT. <i>Rsp. 361</i> e ; PHILSTR. <i>V. Ap. 5, p. 207</i>.<br><span><b>Étym</b>. στρεϐλός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρεβλοω - στρεβλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4762":"<h1>strepho</h1>\n<p>Strong n° 4762 <i>Prononciation [stref'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tourner, retourner</li>\n<li>se détourner (c.à.d. tourner le dos à quelqu'un)\n<ol type=\"a\">\n<li>de quelqu'un qui ne veut plus s'occuper d'un autre</li>\n<li>métaph. se détourner de son ancienne conduite, c.à.d. changer son esprit, se convertir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρέφω</b> <span>(<i>f</i>. στρέψω, <i>ao</i>. ἔστρεψα, <i>pf</i>. ἔστροφα ; <i>pass. f</i>. στρεφθήσομαι, <i>f. 2 att</i>. στραφήσομαι, <i>ao.1 rare</i> ἐστρέφθην, <i>ao.2</i> ἐστράφην, <i>pf</i>. ἔστραμμαι)</span><br><b>A <i>tr.</i></b> tourner, <i>càd. :</i><br><b>   I</b> <i>litt</i>. tourner : πηδάλιον, PD. <i>fr. 15 ;</i> οἴακα, EUR. <i>Hel. 1591,</i> le gouvernail ; πρόσωπον πρός τινα, EUR. <i>Ph. 457,</i> tourner le visage vers qqn ; ὄμμα, PLAT. <i>Rsp. 518</i> c ; ὄμμα πανταχοῖ, EUR. <i>I.T. 68,</i> tourner les yeux, tourner les yeux de tous côtés ; γράμματα, PLAT. <i>Crat. 414</i> c, transposer des lettres ; στρ. ἑαυτόν <i>avec</i> πρός <i>et l’acc</i>. ESCHL. <i>Pr. 707,</i> se tourner vers, <i>etc. ; fig</i>. tourner, faire tourner : τινά <i>avec</i> εἰς <i>et l’acc</i>. AR. <i>Nub. 1455 ; ou</i> πρός <i>et l’acc</i>. EUR. <i>Suppl. 415, etc</i>. tourner <i>ou</i> diriger qqn vers qqe ch. <i>etc. ; particul</i>. faire tourner autour (d’un centre, d’un axe) : τὸν κόσμον, PLAT. <i>Pol. 269</i> e ; τὰ ἄστρα, PLAT. <i>Epin. 977</i> b, le monde, les astres ;<br><b>   II</b> retourner : κάτω θυλάκους, AR. <i>Eccl. 733,</i> retourner des sacs sens dessus dessous ; τὴν γῆν, XÉN. <i>Œc. 16, 15,</i> la terre ; ἄνω καὶ κάτω ESCHL. <i>Eum. 651 ;</i> PLAT. <i>Gorg. 511</i> a ; ἄνω κάτω, DÉM. <i>544, 2,</i> tourner sens dessus dessous, retourner, bouleverser ;<br><b>   III</b> enrouler, tortiller, <i>d’où au pass</i>. être enroulé : ἀλλήλῃσιν, HH. <i>Merc. 411,</i> les unes dans les autres, <i>en parl. de branches ; d’où</i> tresser, XÉN. <i>An. 4, 7, 15 ; p. ext</i>. ourdir une trame, filer, LUC. <i>J. conf. 7 ; fig</i>. élaborer comme une trame (de grandes périodes d’un discours) PLUT. <i>M. 235</i> e ;<br><b>   IV</b> tordre, <i>d’où :</i><br><b>      1</b> démettre par une luxation <i>ou</i> une entorse, tordre, luxer, <i>acc</i>. EPICT. <i>Ench. 29 ; 38 ;</i> ARR. <i>Epict. 3, 15, 4 ; au pass</i>. HDT. <i>3, 129 ;</i> PLAT. <i>Leg. 789</i> e ;<br><b>      2</b> tordre par des tranchées, des coliques, des douleurs <i>en gén</i>. AR. <i>Pl. 1131 ;</i> ANTIPH. (ATH. <i>123</i> b) ; EL. <i>N.A. 11, 14 ; fig</i>. PLAT. <i>Rsp. 330</i> d ;<br><b>   V</b> <i>fig</i>. tourner et retourner par la pensée, rouler dans son esprit, méditer, <i>acc</i>. EUR. <i>Hec. 750 ;</i> τι ἐφ' ἑαυτοῦ, ARR. <i>Epict. 3, 21, 29 ;</i> τι ἐν ἑαυτῷ, EL. <i>N.A. 10, 48,</i> qqe ch. (une pensée, un projet) en soi-même ;<br><b>B <i>intr. :</i><br>      1</b> se tourner, IL. <i>18, 544, 546 ;</i> SOPH. <i>fr. 771 Dind., etc. ;</i><br><b>      2</b> se détourner, <i>càd</i>. faire face : πρός τινα, XÉN. <i>An. 4, 3, 32, etc</i>. à qqn ; <i>abs</i>. XÉN. <i>An. 4, 3, 26 ; au contr</i>. tourner le dos, XÉN. <i>Ages. 2, 3 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. στρέψομαι, <i>ao</i>. ἐστρεψάμην, <i>ao.2 pass</i>. ἐστράφην)</span><br><b>   I</b> se tourner, se retourner, <i>d’où :</i><br><b>      1</b> aller et venir, IL. <i>24, 5 ;</i><br><b>      2</b> <i>p. suite,</i> se tourner en tous sens, IL. <i>12, 42, 45, etc. ;</i> PLAT. <i>Ion 541</i> e, <i>etc. ; fig</i>. στρεφόμενα λέγειν, DH. <i>Rhet. 15,</i> dire des choses qui se laissent tourner et retourner, <i>càd</i>. qui se laissent interpréter de façon différente ;<br><b>   II</b> se détourner, s’éloigner, SOPH. <i>O.C. 1648, etc. ;</i> ἐκ χώρης, IL. <i>6, 516,</i> d’un pays ; στραφέντες ἔφευγον, XÉN. <i>Cyr. 3, 3, 63,</i> ils firent demi-tour et s’enfuirent ; <i>fig</i>. se détourner, cesser, <i>en parl. de la colère,</i> SOPH. <i>Tr. 1136 ;</i><br><b>   III</b> s’enrouler : χερσίν τινος, OD. <i>9, 435,</i> enrouler ses mains à qqe ch., s’accrocher les mains à qqe ch. ;<br><b>   IV</b> tourner dans le même lieu, <i>d’où :</i><br><b>      1</b> séjourner, s’arrêter (en un lieu) : ἐπὶ γῇ, PLAT. <i>Ep. 335</i> b, sur terre ;<br><b>      2</b> <i>fig. (cf. le lat</i>. versari) résider dans, se trouver dans, <i>avec</i> ἐν <i>et le dat</i>. PLAT. <i>Theæt. 194</i> b ; <i>ou</i> περί <i>et l’acc</i>. ARSTT. <i>Metaph. 3, 2, 20 ;</i><br><b>      3</b> <i>fig</i>. tourner autour de, s’attacher à, <i>avec</i> ἐν <i>et le dat</i>. PLAT. <i>Theæt. 181</i> c, <i>etc. ; p. suite,</i> prendre soin de, se soucier de, <i>gén</i>. SOPH. <i>Aj. 1116 ;</i><br><b>   V</b> se tourner et se retourner, s’agiter, <i>particul</i>. pour intriguer. PLAT. <i>Phædr. 236</i> e ; <i>avec un acc. :</i> τι, AR. <i>Ach. 385,</i> machiner qqe ruse ; στροφάς, PLAT. <i>Rsp. 405</i> c, ourdir des intrigues ;<br><b>   VI</b> (<i>au pf</i>.) être tourné <i>ou</i> dirigé, <i>en parl. d’un lieu, avec</i> ἐπί <i>et l’acc</i>. POL. <i>2, 15, 8</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Le pf</i>. ἔστροφα <i>seul. dans</i> THGNT. (ATH. <i>104</i> c) ; <i>ao. itér. épq. 3 pl</i>. στρέψασκον, IL. <i>18, 546 ; ao. pass. ion. et dor</i>. ἐστράφθην, THCR. <i>Idyl. 7, 132 ;</i> SOPHR. <i>78 ;</i> THCR. <i>Idyl. 7, 132</i>.<br><span><b>Étym</b>. <i>pré-grec ; cf</i>. στροφή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρεφω - στρέφω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 18 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Luc (7)</li>\n<li>Jean (3)</li>\n<li>Actes (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4763":"<h1>streniao</h1>\n<p>Strong n° 4763 <i>Prononciation [stray-nee-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être folâtre, vivre dans le luxe, faire preuve d'une mollesse provocante</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρηνιάω-ῶ :<br>      1</b> être orgueilleux, insolent, ANTIPH. (<i>Com. fr. 3, 44</i>) ; DIPH. (<i>Com. fr. 4, 429</i>) ; NT. <i>Apoc. 18, 7 et 9 ;</i><br><b>      2</b> vivre dans la mollesse, SOPHIL. (<i>Com. fr. 3, 582</i>).<br><span><b>Étym</b>. στρῆνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρηνιαω - στρηνιάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4764":"<h1>strenos</h1>\n<p>Strong n° 4764 <i>Prononciation [stray'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>luxe</li>\n<li>ardent désir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>στρῆνος, εος-ους (τὸ)</b> orgueil, insolence, ANTH. <i>7, 686 ;</i> SPT. <i>4Reg. 19, 28 ;</i> luxe, NT. <i>Apoc. 18, 3, etc</i>.<br><br>\n➁ <b>στρῆνος, ου (ὁ)</b> désir violent, passion, LYC. <i>438</i>.<br><span><b>Étym</b>. <i>cf</i>. στρῆνος¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρηνος - στρῆνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4765":"<h1>strouthion</h1>\n<p>Strong n° 4765 <i>Prononciation [stroo-thee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un petit oiseau, de l'espèce du moineau, un passereau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>στρουθίον, ου (τὸ)</b> petit moineau, ANAXANDR. (<i>Com. fr. 3, 164</i>) ; ARSTT. <i>H.A. 5, 2, 4 ; 9, 7, 10 ;</i> ATH. <i>571</i> e, <i>654</i> b ;.<br><span><b>Étym</b>. στρουθός.</span><br><br>\n➁ <b>στρούθιον, ου (τὸ)</b> herbe à foulon <i>ou</i> saponaire pour nettoyer, HPC. <i>571, 54 ;</i> TH. <i>H.P. 6, 4, 3 ; 6, 8, 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρουθιον - στρουθίον</font>\n<br><br>diminutif de strouthos (un moineau)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4766":"<h1>stronnumi</h1>\n<p>Strong n° 4766 <i>Prononciation [strone'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étendre</li>\n<li>meubler</li>\n<li>arranger, étendre sa couche ou un divan</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στρωννύω</b> <i>(seul. prés</i>. ARSTD. <i>14, 216 ;</i> GEOP. <i>19, 2 ; et impf</i>. ἐστρώννυον, NT. <i>Matth. 21, 8) c</i>. στρώννυμι.<br><br>\n<b>στρώννυμι</b> <span>(<i>f</i>. στρώσω, <i>ao</i>. ἔστρωσα, <i>pf</i>. ἔστρωκα, <i>pl.q.pf</i>. ἐστρώκειν ; <i>pass. f</i>. στρωθήσομαι, <i>ao</i>. ἐστρώθην, <i>pf</i>. ἔστρωμαι, <i>pl.q.pf</i>. ἐστρώμην)</span> étendre (un tapis, <i>etc</i>.) PLUT. <i>Artax. 22 ;</i> ATH. <i>581 ; au pass</i>. PLAT. <i>Rsp. 372</i> b.<br><span><b>Étym</b>. στόρνυμι, στορέννυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στρωννυμι - στρωννύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4767":"<h1>stugnetos</h1>\n<p>Strong n° 4767 <i>Prononciation [stoog-nay-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>haï, détesté, odieux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στυγητός, ή, όν</b> <span>[ῠ]</span><br><b>      1</b> haï, exécré, ESCHL. <i>Pr. 592 ;</i><br><b>      2</b> haïssable, odieux, NT. <i>Tit. 3, 3 ;</i> HLD. <i>5, 29</i>.<br><span><b>Étym</b>. <i>vb. de</i> στυγέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στυγητος - στυγητός</font>\n<br><br>vient d'un dérivé du mot stugo (haïr)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4768":"<h1>stugnazo</h1>\n<p>Strong n° 4768 <i>Prononciation [stoog-nad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être triste, affligé</li>\n<li>métaph. du ciel couvert de nuages</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στυγνάζω<br>      1</b> être d’humeur sombre : ἐπί τινι, NT. <i>Marc. 10, 22,</i> au sujet de qqe ch. ;<br><b>      2</b> avoir l’air sombre, <i>fig</i>. στυγνάζει ὁ οὐρανός, NT. <i>Matth. 16, 3,</i> le ciel est sombre, menaçant.<br><span><b>Étym</b>. στυγνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στυγναζω - στυγνάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4769":"<h1>stulos</h1>\n<p>Strong n° 4769 <i>Prononciation [stoo'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un pilier</li>\n<li>une colonne\n<ol type=\"a\">\n<li>colonnes de feu c.à.d. flammes s'élevant comme des piliers</li>\n</ol>\n</li>\n<li>un appui ou support</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>στῦλος, ου (ὁ)</b> <span>[ῡ]</span><br><b>      1</b> colonne, HDT. <i>2, 169 ;</i> ESCHL. <i>Ag. 898 ;</i> EUR. <i>I.T. 50 ; fig. càd</i>. soutien, appui, EUR. <i>I.T. 57 ;</i><br><b>      2</b> poteau, EUR. <i>fr. 202 ;</i> POL. <i>1, 22, 4</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *sth₂-u-lo-, pilier, <i>de la</i> R. *steh₂-, <i>v</i>. ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">στυλος - στῦλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Galates (1)</li>\n<li>1 Timothée (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4770":"<h1>Stoikos</h1>\n<p>Strong n° 4770 <i>Prononciation [sto-ik-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Stoïciens (Angl. Stoics) = « appartenant au portique »\n<ol><li>une des écoles philosophiques que Paul rencontra à Athènes, fondée par Zénon de Citium dans l'île de Chypre. Pour eux la vertu est une résignation à l'égard de la destinée, le sage se montre insensible aux coups du sort, et il faut acquérir courage et sobriété.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Στοϊκός, ή, όν</b>, <i>poét. c</i>. Στωϊκός, ANTH. <i>9, 496</i>.<br><br>\n<b>Στωϊκός, ή, όν</b>, de l’école du Portique, des Stoïciens, DH. <i>Comp. 2 ;</i> DL. <i>6, 14 ; subst</i>. ὁ Στ. Stoïcien, DL. <i>7, 5 ;</i> NT. <i>Ap. 17, 18 ; cf</i>. Στοϊκός ; ἡ στοϊκὴ αἵρεσις, σχολή <i>ou</i> φιλοσοφία, DH. <i>5, 8 Reiske ;</i> STR. <i>14, 6, 3 Kram. ;</i> PLUT. <i>M. 605, 329, etc</i>. la secte, l’école <i>ou</i> la philosophie stoïcienne.<br><span><b>Étym</b>. *στωά, <i>p</i>. στοά.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Στωικος - Στοϊκός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4771":"<h1>su</h1>\n<p>Strong n° 4771 <i>Prononciation [soo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύ</b> <span>[ῠ]</span> σοῦ, σοί, σέ ; <i>pl</i>. ὑμεῖς, ὑμῶν, ὑμῖν, ὑμᾶς ; <i>duel</i> σφῶϊ <i>ou</i> σφώ, <i>gén. dat</i>. σφῶϊν <i>ou</i> σφῷν, tu, toi ; vous, vous deux ; <i>se place soit devant le nom de pers. ou de chose auquel on s’adresse,</i> IL. <i>21, 193, etc. ; soit après,</i> AR. <i>Pl. 1069, etc</i>.<br><span><b><span class=\"arrow\"></span> <i>Nom</i>.</b> σύ, OD. <i>18, 31, etc. — <b>Voc</b></i>. σύ, IL. AR. <i>ll. cc. — Éol. et dor</i>. τύ, SAPPH. <i>fr. 1, 13 Bgk ;</i> AR. <i>Ach. 777, 861, etc. ;</i> ORACL. (HDT. <i>4, 157) ; béot</i>. τού, CORINN. <i>fr. 1 et 5 Bgk ; épq</i>. τύνη <span>[ῡ]</span> IL. <i>5, 485 ;</i> CHILON (PLUT. <i>M. 150</i> a). — <b><i>Gén</i>.</b> σοῦ, HOM. ATT. ; <i>ion. et dor</i>. σέο <i>et</i> σεῦ, HOM. PD. HDT. ; <i>ion</i>. σέθεν, HOM. LYR. TRAG. ; <i>épq</i>. σεῖο, IL. <i>3, 137, etc. ;</i> σου <i>enclit. chez les Att.,</i> σεο <i>chez les Ion. ; dor</i>. τέο, ALCM. <i>17 ;</i> τεῦ, PLUT. <i>Pyrrh. 26, M. 241</i> a ; <i>enclit</i>. τευ, THCR. <i>Idyl. 5, 19 ; 7, 25 ; 8, 82, etc. ;</i> τεοῦ, SOPHR. <i>et</i> EPICH. (DYSC. <i>Pron. 96</i> c) ; CALL. <i>Cer. 98 ; épq</i>. τεοῖο, IL. <i>8, 37, 468 ; éol. et dor</i>. τεοῦς (<i>sel. Buttm</i>. τέους) ; CORINN. <i>fr. 24 Bgk ;</i> SOPHR. (DYSC. <i>Pron. p. 95</i> c) ; THCR. <i>Idyl. 11, 25 ; 18, 41 ; ou</i> τεῦς, CORINN. <i>fr. 24 Bgk ;</i> EPICH. (DYSC. <i>Pron. p. 96</i> a) ; <i>enclit</i>. τεος, SOPHR. (DYSC. <i>Pron. p. 95</i> c) ; <i>autres formes dor</i>. τίω, τίως, τίος, DYSC. <i>Pron. p. 95</i> c, <i>96</i> c ; <i>éol</i>. τιοῦς, DYSC. <i>Pron. p. 95</i> c. — <b><i>Dat</i>.</b> σοί, HOM. ATT. ; <i>encl</i>. σοι, ATT. ; <i>dor. et ion</i>. τοί, HOM. HDT., <i>ou</i> τίν <span>[ῑ]</span> PD. <i>I. 6, 5 ;</i> THCR. <i>Idyl. 2, 20 ; 3, 33 ; 5, 52 ; ou</i> τίν <span>[ῐ]</span> ALCM. <i>16 ;</i> PD. <i>P. 1, 56 ; 8, 97 ; N. 10, 54 ; épq</i>. τεΐν, IL. <i>11, 201 ;</i> OD. <i>4, 619 ;</i> ORACL. (HDT. <i>5, 60, 61</i>) ; CALL. <i>L. Pall. 37. — <b>Acc</b></i>. σέ, <i>encl</i>. σε, HOM. ATT. <i>etc. ; dor</i>. τέ, ALCM. <i>52 ;</i> THCR. <i>Idyl. 1, 5 ; ou</i> τύ, AR. <i>Eq. 1225, Ach. 730, 779 ;</i> THCR. <i>Idyl. 56, 78 ;</i> τεΐ, ALCM. <i>53 ; et</i> τίν, CORINN. <i>fr. 4 Bgk ;</i> THCR. <i>Idyl. 11, 39. — Plur. nom</i>. ὑμεῖς, HOM. ATT. <i>etc. ; épq. et éol</i>. ὔμμες, HOM. SAPPH. <i>26 ; dor</i>. ὑμές, SOPHR. <i>33 ;</i> AR. <i>Ach. 760, 761, 862 ; béot</i>. οὐμές, CORINN. <i>fr. 6 ; postér</i>. ὑμέες, PARTH. <i>fr. 14 Martini</i> (DYSC. <i>Pron. p. 118</i> b). — <i>Gén</i>. ὑμῶν, ATT. ; <i>chez Hom</i>. ὑμέων (<i>dissyll.) et</i> ὑμείων, IL. <i>7, 159, etc. ; éol</i>. ὐμμέων, ALC. <i>93 (77) ; béot</i>. οὐμίων, CORINN. <i>fr. 22 Bgk. — Dat</i>. ὑμῖν, HOM. ATT. <i>etc. ; chez les Trag</i>. ὑμίν <i>ou</i> ὗμιν, SOPH. <i>Aj. 864, 1242, 1264 ; El. 804, 1328, etc. ;</i> ὕμιν, OD. <i>1, 376 ; 2, 141 etc. ; cf</i>. EM. <i>432, 36 ; éol. et épq</i>. ὔμμι <span>[ῐ]</span> <i>et</i> ὔμμιν <span>[ῐ]</span>, OD. <i>2, 316 ; 11, 335, etc. ;</i> HÉS. <i>Sc. 328 ;</i> SAPPH. <i>17. — Acc</i>. ὑμᾶς, ATT. ; <i>chez Hom</i>. ὑμέας (<i>dissyll.) ; éol. et épq</i>. ὔμμε, IL. <i>11, 781, etc. ;</i> PD. <i>I. 5, 28 ;</i> ESCHL. <i>Eum. 620 ;</i> SOPH. <i>Ant. 846 ;</i> THCR. <i>Idyl. 5, 145 ;</i> XÉN. <i>Hell. 4, 4, 10 ; dor</i>. ὑμέ, ALCM. <i>37 ;</i> SOPHR. <i>99 Ahrens ;</i> AR. <i>Lys. 87 ; Ach. 737, 739. — Les formes ὔμμες, ὔμμι, ὔμμε sont les seuls exemples où, dans la langue épq., υ ait l’esprit doux. — Duel nom.-acc</i>. σφῶϊ, HOM. ; <i>et</i> σφώ (<i>non</i> σφῳ) IL. <i>1, 574 ; 11, 782 ; 13, 47 ; 15, 146 ;</i> ATT. ; <i>gén.-dat</i>. σφῶϊν, HOM. ; <i>par contr</i>. σφῷν, OD. <i>4, 62 ;</i> ATT. — σύ <i>renforcé en</i> σύ γε, <i>d’ordin. en un seul mot</i> σύγε (<i>comme</i> ἔγωγε), HOM. ATT. ; <i>dor</i>. τύγε <i>ou</i> τύγα, TIMOCR. <i>fr. 1, 1, 2 Bgk ;</i> EPICH. (PLUT. <i>Popl. 15</i>) ; THCR. <i>Idyl. 5, 69, 71 ;</i> PLUT. <i>Pyrrh. 26, etc. ; dat</i>. σοίγε, <i>acc</i>. σέγε, HOM. ; <i>de même</i> σύπερ, IL. <i>24, 398. Duel renforcé</i> ἀμφοτέρω σφῶϊ, IL. <i>7, 280 ; 10, 552</i>.<br><span><b>Étym</b>. <i>sg</i>. σύ, <i>indo-europ</i>. *tuH-, <i>cf. lat</i>. tū ; <i>le</i> σ <i>initial d’après l’acc</i>. σέ <i>p</i>. *tue ; <i>plur</i>. ὔμμε <i>de l’acc</i>. *usmé, <i>cf. sscr</i>. yuṣmā́n ; <i>duel</i> σφῶϊ, <i>v</i>. σφε-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συ - σύ</font>\n<ol><li>pronom de la seconde personne du singulier</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n177 fois dans 162 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (18)</li>\n<li>Marc (9)</li>\n<li>Luc (27)</li>\n<li>Jean (62)</li>\n<li>Actes (17)</li>\n<li>Romains (12)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (7)</li>\n<li>Tite (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (8)</li>\n<li>Jacques (5)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G4772":"<h1>suggeneia</h1>\n<p>Strong n° 4772 <i>Prononciation [soong-ghen'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une relation, la parenté</li>\n<li>parenté, affinité, relations collectives, famille</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγγένεια</b>, <i>anc. att</i>. <b>ξυγγένεια, ας (ἡ) :<br>      1</b> parenté, THC. <i>3, 65 ;</i> XÉN. <i>Hell. 2, 4, 21 ;</i> EUR. <i>I.A. 492 ;</i> τινι, PLAT. <i>Pol. 307</i> d, <i>etc. ;</i> πρός τινα, ISOCR. <i>49</i> b, <i>119</i> d, avec qqn ; <i>mais non en parl. des relations de parenté entre parents et enfants,</i> IS. <i>72, 32 ; cf</i>. DS. <i>13, 20 ; en parl. d’animaux,</i> ARSTT. <i>H.A. 6, 11, 7, etc. ; p. anal. en parl. des rapports d’une colonie avec sa métropole,</i> ORAT. ;<br><b>      2</b> parenté, ensemble des parents, famille, PLAT. <i>Gorg. 472</i> b ; <i>p. suite,</i> membre d’une famille, parent, EUR. <i>Or. 1233 ; au pl</i>. les familles, DÉM. <i>25, 87 ; 796, 17 ; particul. en parl. de deux fils,</i> DS. <i>13, 20 ;</i><br><b>      3</b> <i>p. ext</i>. classe, genre, espèce, ARSTT. <i>An. post. 1, 9, 2</i>.<br><span><b>Étym</b>. συγγενής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγγενεια - συγγένεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4773":"<h1>suggenes</h1>\n<p>Strong n° 4773 <i>Prononciation [soong-ghen-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de même parent, allié, parent, lié par le sang</li>\n<li>dans un sens plus large, même race, un compatriote</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·γενής</b>, <i>anc. att</i>. <b>ξυγ·γενής, ής, ές :<br>   I</b> né avec, <i>càd. :</i><br><b>      1</b> qui vient de naissance, inné, naturel, PD. <i>O. 13, 16 ;</i> ESCHL. <i>Eum. 691, etc. ;</i> συγγενεῖς μῆνες, SOPH. <i>O.R. 1082,</i> les mois nés avec moi, <i>càd</i>. avec lesquels a commencé ma vie ; σ. τρίχες, ARSTT. <i>H.A. 3, 11, 7, etc</i>. les cheveux qui naissent avec l’homme, <i>p. opp. à la barbe ;</i><br><b>      2</b> de même origine, de même famille, parent : <i>abs</i>. ESCHL. <i>Pr. 14 ;</i> EUR. <i>Andr. 887 ;</i> σ. τινι, HDT. <i>1, 109, etc. ;</i> ATT. ; τινος, PLAT. <i>Rsp. 487</i> a, <i>etc. ;</i> AR. <i>Pax 618, etc</i>. parent de qqn ; <i>subst</i>. ὁ, ἡ σ. MÉN. <i>4, 283 Meineke</i> parent, parente ; οἱ συγγενεῖς, PD. <i>P. 4, 236 ;</i> HDT. <i>2, 91,</i> les parents ; <i>mais non en parl. des enfants à l’égard du père et de la mère,</i> IS. <i>72, 12 ;</i> τὸ συγγενές, ESCHL. <i>Pr. 289, etc. ;</i> THC. <i>3, 82, etc</i>. la parenté ; <i>en parl. d’animaux,</i> ARSTT. <i>H.A. 5, 1, 6 ; G.A. 2, 8, 2, etc. ; p. anal. en parl. de peuples, de tribus,</i> τὸ ξ. THC. <i>1, 95,</i> la parenté (entre populations de même origine) ; <i>p. suite,</i> qui concerne des parents, de parent : σ. χείρ, SOPH. <i>O.C. 1387,</i> main d’un parent ; σ. γάμος, ESCHL. <i>Pr. 885,</i> mariage entre parents ; <i>p. ext. à la cour du roi de Perse,</i> parent, <i>titre d’honneur conféré par le roi,</i> XÉN. <i>Cyr. 1, 4, 27 ; 2, 2, 31 ;</i> DS. <i>16, 50 ;</i><br><b>   II</b> qui a de l’affinité avec, semblable, analogue, <i>abs</i>. AR. <i>Eq. 1280, etc. ;</i> σ. τινι, PLAT. <i>Leg. 814</i> d, <i>etc. ;</i> ARSTT. <i>G.A. 5, 8, 1, etc. ;</i> τινος, PLAT. <i>Phil. 31</i> a, <i>etc. ;</i> semblable <i>ou</i> analogue à qqn <i>ou</i> à qqe ch. ; τὰ συγγενῆ, ARSTT. <i>Rhet. 3, 2, 12,</i> les choses de même sorte, <i>joint à</i> τὰ ὁμοειδῆ.<br><span>•<i> Sup</i>. συγγενέστατος, IS. <i>85, 25,</i> très proche parent.<br><span><b><span class=\"arrow\"></span></b> <i>Duel</i> συγγένεε, PLAT. <i>Eryx. 396</i> d ; ξυγγενῆ, AR. <i>Av. 368</i>.<br><span><b>Étym</b>. σύν, γένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγγενης - συγγενής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (4)</li>\n</ul>\n</td></tr>\n</table>","G4774":"<h1>suggnome</h1>\n<p>Strong n° 4774 <i>Prononciation [soong-gno'-may]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pardon, indulgence, concession, consentement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγγνώμη</b>, <i>anc. att</i>. <b>ξυγγνώμη, ης (ἡ) :<br>      1</b> pardon : συγγνώμην ἔχειν τινί, <i>avec un n. de pers. p. suj</i>. accorder le pardon à qqn, HDT. <i>1, 116, 155 ;</i> ATT. ; τινός, HDT. <i>6, 86 ;</i> SOPH. <i>El. 400, etc. ;</i> περί τι, ARSTT. <i>Nic. 6, 11, 1,</i> pour qqe ch. ; <i>avec un inf</i>. SOPH. <i>Aj. 1322 ; avec un n. de chose p. suj</i>. entraîner le pardon pour qqn, être pardonné <i>ou</i> pardonnable, SOPH. <i>Tr. 327 ; cf</i>. THC. <i>3, 44 ;</i> PLUT. <i>M. 1118</i> e ; συγγνώμην αἰτεῖσθαι, PLAT. <i>Criti. 106</i> b, demander son pardon ; συγγνώμην ποιήσασθαι, HDT. <i>2, 110 ;</i> διδόναι, POL. <i>8, 1, 2 ;</i> νέμειν, PAUS. <i>2, 27, 4 ;</i> ἀπονέμειν, LUC. <i>Nigr. 14,</i> accorder le pardon, pardonner ; συγγνώμης τυγχάνειν, XÉN. <i>Mem. 1, 7, 4,</i> obtenir son pardon ; συγγνώμης τυγχάνειν τινός, EUR. <i>Hipp. 1326 ;</i> ὑπέρ τινος, ISOCR. <i>289</i> d, obtenir son pardon pour qqe ch. ; παρά τινος, LYS. <i>190, 22,</i> obtenir le pardon de qqn ; συγγνώμην λαμϐάνειν παρά τινος, PLAT. <i>Phil. 65</i> c, <i>m. sign. ;</i> ξυγγνώμην λαμϐάνειν <i>avec un inf</i>. THC. <i>3, 40,</i> obtenir son pardon pour, <i>etc. ;</i> συγγνώμη ἐστί, <i>avec une prop. inf</i>. THC. <i>4, 61 ; 5, 81 ;</i> DÉM. <i>415, 16 ; ou avec</i> εἰ, THC. <i>1, 24 ; ou</i> ἐάν, PLAT. <i>Hipp. mi. 372</i> a, c’est chose pardonnable, si, <i>etc. ; avec un part. :</i> τούτων μὴ ἀπεχομένῳ σοι ἔσται πολλὴ συγγνώμη, PLAT. <i>Theæt. 197</i> a, ce sera chose bien pardonnable, si tu ne t’abstiens pas de ces choses,<br><b>      2</b> indulgence, concession, permission, ARSTT. <i>Nic. 6, 11, 1 ;</i> NT. <i>1Cor. 7, 6</i>.<br><span><b>Étym</b>. συγγιγνώσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγγνωμη - συγγνώμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4775":"<h1>sugkathemai</h1>\n<p>Strong n° 4775 <i>Prononciation [soong-kath'-ay-mahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>s'asseoir ensemble, s'asseoir avec quelqu'un d'autre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κάθημαι</b> (<i>seul. prés</i>.) ;<br><b>   I. 1</b> être assis avec <i>ou</i> à côté de, HDT. <i>3, 68 ;</i> EUR. <i>Bacch. 810 ;</i><br><b>      2</b> siéger ensemble, XÉN. <i>An. 5, 7, 21 ;</i> περὶ εἰρήνης, THC. <i>5, 55,</i> pour traiter de la paix ;<br><b>   II</b> être assis <i>ou</i> affaissé en même temps, STR. <i>775 ;</i> LUC. <i>Pseud. 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. συγκάτημαι, HDT. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκαθημαι - συγκάθημαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4776":"<h1>sugkathizo</h1>\n<p>Strong n° 4776 <i>Prononciation [soong-kath-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire asseoir ensemble, placer ensemble</li>\n<li>être assis ensemble</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·καθίζω</b> <span>(<i>f</i>. -ιζήσω, <i>ao</i>. συνεκάθισα, <i>pf</i>. συγκεκάθικα, <i>etc</i>.)</span> <span>[ᾰ]</span><br><b>   I <i>tr.</i></b> asseoir <i>ou</i> établir avec <i>ou</i> ensemble, SPT. <i>Ex. 18, 13 ;</i><br><b>   II <i>intr.</i></b> s’asseoir en même temps, siéger ensemble, SPT. <i>1Esdr. 9, 6 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> siéger ensemble, XÉN. <i>Hell. 5, 2, 35 ;</i> DÉM. <i>1434, 6 ;</i> LUC. <i>M. cond. 33 ;</i><br><b>      2</b> ramener ses jambes sous soi pour se poser à terre, <i>en parl. de quadrupèdes,</i> ARSTT. <i>H.A. 2, 1, 9 ; 2, 6, 27, etc. ; en parl. de pers</i>. s’affaisser, PLUT. <i>Arat. 21</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκαθιζω - συγκαθίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4777":"<h1>sugkakopatheo</h1>\n<p>Strong n° 4777 <i>Prononciation [soong-kak-op-ath-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souffrir de privation ensemble avec quelqu'un, tenir bon dans une mauvaise situation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κακοπαθέω-ῶ</b> <span>[ᾰᾰ]</span>, souffrir avec, <i>dat</i>. NT. <i>2Tim. 1, 8</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκακοπαθεω - συγκακοπαθέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4778":"<h1>sugkakoucheo</h1>\n<p>Strong n° 4778 <i>Prononciation [soong-kak-oo-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être maltraité avec un autre</li>\n<li>partager des persécutions ou devenir un compagnon de misère</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κακουχέομαι-οῦμαι</b> <span>[ᾰ]</span> être maltraité avec <i>ou</i> de même que, <i>dat</i>. NT. <i>Hebr. 11, 25</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκακουχεω - συγκακουχέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4779":"<h1>sugkaleo</h1>\n<p>Strong n° 4779 <i>Prononciation [soong-kal-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appeler ensemble, assembler</li>\n<li>inviter, convoquer à soi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·καλέω-ῶ</b> <span>(<i>f</i>. -έσω, <i>att</i>. -ῶ ; <i>ao</i>. συνεκάλεσα, <i>etc</i>.)</span> <span>[ᾰ]</span><br><b>      1</b> appeler en même temps : τινά τινι, XÉN. <i>Cyr. 8, 4, 1,</i> qqn en même temps que qqn ;<br><b>      2</b> <i>p. suite,</i> convoquer, IL. <i>2, 55 ; 10, 302 ;</i> HDT. <i>1, 206 ;</i> ESCHL. <i>Suppl. 517 ;</i> AR. <i>Av. 201 ;</i> τινα <i>avec un inf</i>. LUC. <i>V. auct. 1,</i> convoquer qqn pour, <i>etc. ;</i><br><b><i>Moy.</i></b> convoquer près de soi <i>ou</i> pour soi, HDT. <i>2, 160 ;</i> NT. <i>Luc. 9, 1, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. épq</i>. συγκαλέω, HOM. <i>Ep. 14, 8</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκαλεω - συγκαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4780":"<h1>sugkalupto</h1>\n<p>Strong n° 4780 <i>Prononciation [soong-kal-oop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>couvrir de tous côtés, cacher entièrement, recouvrir complètement, voiler complètement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·καλύπτω</b> <span>[ᾰ]</span><br><b>      1 <i>tr.</i></b> couvrir entièrement, envelopper, EUR. <i>Ph. 872 ;</i> PLAT. <i>Rsp. 452</i> d ;<br><b>      2 <i>intr.</i></b> s’envelopper de, <i>dat</i>. THÉM. <i>59</i> b ;<br><b><i>Moy.</i></b> s’envelopper, XÉN. <i>Cyr. 8, 7, 28 ; Conv. 1, 14 ;</i> PLUT. <i>Num. 10</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκαλυπτω - συγκαλύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4781":"<h1>sugkampto</h1>\n<p>Strong n° 4781 <i>Prononciation [soong-kamp'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>plier ensemble, courber complètement</li>\n<li>métaph. assujettir quelqu'un à l'erreur et la dureté de cœur, figure provenant des captifs courbant le cou pour passer sous le joug</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κάμπτω</b>, <i>anc. att</i>. <b>ξυγ·κάμπτω</b> <span>(<i>ao. pass</i>. συνεκάμφθην, <i>pf. part</i>. συγκεκαμμένος)</span><br><b>      1 <i>tr.</i></b> contracter <i>ou</i> ramasser sur soi en courbant, en pliant, HPC. <i>Art. 791 ;</i> PLAT. <i>Phæd. 60</i> b ; <i>au pass</i>. XÉN. <i>Eq. 7, 2 ; 12, 5 ;</i> PLAT. <i>Phæd. 98</i> d ; ARSTT. <i>Probl. 6, 3, etc. ;</i><br><b>      2 <i>intr.</i></b> se courber, SPT. <i>4Reg. 4, 35</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκαμπτω - συγκάμπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4782":"<h1>sugkatabaino</h1>\n<p>Strong n° 4782 <i>Prononciation [soong-kat-ab-ah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>descendre avec\n<ol type=\"a\">\n<li>de ceux qui descendent d'un endroit sur la hauteur vers un endroit plus bas, comme par exemple de Jérusalem à Césarée</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·καταϐαίνω</b> <span>(<i>ao.2</i> συγκατέϐην, <i>etc</i>.)</span><br><b>   I</b> <i>au propre :</i><br><b>      1</b> descendre avec, <i>dat</i>. EUR. <i>Andr. 505 ; particul</i>. descendre ensemble (de la ville au Pirée) THC. <i>6, 30 ;</i><br><b>      2</b> tomber en touffe sur, <i>dat. en parl. de cheveux,</i> PHILSTR. <i>Ep. 58, p. 943 ;</i><br><b>      3</b> descendre au secours de, descendre pour assister, ESCHL. <i>Eum. 1046 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> se jeter dans : εἰς κίνδυνον, POL. <i>3, 89, 8 ;</i> εἰς πόλεμον, POL. <i>5, 66, 7,</i> en venir à s’exposer à un danger, à une guerre ;<br><b>      2</b> s’accorder avec, <i>avec</i> εἰς <i>et l’acc</i>. POL. <i>3, 90, 5 ; 4, 4, 5, etc. ;</i><br><b>      3</b> condescendre, consentir : εἴς τι, POL. <i>3, 10, 1 ; 4, 45, 4,</i> à qqe ch. ; <i>abs</i>. POL. <i>26, 10, 4 ; particul</i>. céder sur le prix d’une chose, POL. <i>22, 9, 12</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκαταβαινω - συγκαταβαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4783":"<h1>sugkatathesis</h1>\n<p>Strong n° 4783 <i>Prononciation [soong-kat-ath'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une mise en commun, déposer un vote\n<ol type=\"a\">\n<li>de là approbation, assentiment, accord</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγκατάθεσις, εως (ἡ) :<br>      1</b> assentiment, approbation, POL. <i>2, 58, 11 ; particul. t. stoïc</i>. accord de l’esprit avec les perceptions, PLUT. <i>M. 1055</i> b, <i>1056</i> c, <i>etc. ;</i><br><b>      2</b> concorde, NT. <i>2Cor. 6, 16 ;</i><br><b>      3</b> soumission, PLUT. <i>Ant. 24</i>.<br><span><b>Étym</b>. συγκατατίθημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκαταθεσις - συγκατάθεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4784":"<h1>sugkatatithemai</h1>\n<p>Strong n° 4784 <i>Prononciation [soong-kat-at-ith'-em-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>déposer ensemble avec un autre</li>\n<li>déposer son vote dans l'urne avec un autre</li>\n<li>consentir à, voter pour, être d'accord avec, agréer, admettre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κατατίθημι</b>, <i>au moy</i>. συγκατατίθεμαι <span>[τῐ]</span><br><b>      1</b> déposer en même temps, IS. <i>59, 28 ;</i><br><b>      2</b> donner son assentiment : τινὶ τὴν αὐτὴν δόξαν περί τινος, PLAT. <i>Gorg. 501</i> c, à qqn au sujet de qqe ch. (<i>litt</i>. déposer le même vote que qqn) ; <i>avec un dat. seul :</i> σ. τινί, PHILIPP. (DÉM. <i>283, 22</i>) donner son assentiment à qqe ch. ; <i>avec double rég. :</i> τινὶ σ. τινί, POL. <i>3, 71, 5,</i> être d’accord avec qqn pour qqe ch. ; σ. ὅτι, ARSTT. <i>Top. 3, 1, 1,</i> accorder qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκατατιθεμαι - συγκατατίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4785":"<h1>sugkatapsephizo</h1>\n<p>Strong n° 4785 <i>Prononciation [soong-kat-aps-ay-fid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>déposer un bulletin dans l'urne (c.à.d. par vote) pour désigner quelqu'un un à une place, vote pour quelqu'un un</li>\n<li>vote contre avec les autres, c.à.d. condamner avec les autres</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·καταψηφίζω</b>, élire ensemble, NT. <i>Ap. 1, 26 ;</i><br><b><i>Moy.</i></b> condamner en même temps, PLUT. <i>Them. 21</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκαταψηφιζω - συγκαταψηφίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4786":"<h1>sugkerannumi</h1>\n<p>Strong n° 4786 <i>Prononciation [soong-ker-an'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mêler ensemble</li>\n<li>unir\n<ol type=\"a\">\n<li>grouper plusieurs parties pour les combiner dans une structure, qui est le corps</li>\n<li>unir une chose à une autre, fusionner, pénétrer dans</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κεράννυμι</b>, <i>anc. att</i>. <b>ξυγ·κεράννυμι</b> <span>[ῡ]</span> <span>(<i>f</i>. -κεράσω, <i>att</i>. -κερῶ <i>etc. ; pass. f</i>. συγκραθήσομαι <span>[ᾱ]</span>, <i>ao</i>. συνεκράσθην <span>[ᾱ]</span> <i>ou</i> συνεκεράσθην, <i>pf</i>. συγκέκραμαι <span>[ᾱ]</span>)</span><br><b>      1</b> mêler avec, mélanger : τί τινι, ANTH. <i>11, 154,</i> une chose à une autre ; <i>fig</i>. PLAT. <i>Phil. 50</i> a ; <i>avec un seul rég</i>. mélanger, faire un mélange de, <i>acc</i>. ANTH. <i>12, 168 ; fig</i>. PLAT. <i>Crat. 424</i> e, <i>etc. ; au pass</i>. être mélangé, XÉN. <i>Cyn. 3, 1 ; fig</i>. être formé par un échange (de bon vouloir) <i>en parl. d’amitié,</i> HDT. <i>4, 152 ;</i><br><b>      2</b> <i>t. de gr</i>. contracter (deux voyelles en une) DRAC. <i>157 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. συνεκερασάμην)</span><br><b>   I <i>tr.</i></b> mêler pour soi : φιλίαν πρός τινα, HDT. <i>7, 151,</i> contracter amitié avec qqn ;<br><b>   II <i>intr. :</i><br>      1</b> se lier avec, <i>dat</i>. XÉN. <i>Cyr. 1, 4, 1 ;</i><br><b>      2</b> être aux prises avec, en proie à, être plongé dans, <i>dat</i>. SOPH. <i>Ant. 1311 ;</i> AR. <i>Pl. 853, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass. ion</i>. συνεκρήθην, HDT. <i>4, 152</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκεραννυμι - συγκεράννυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4787":"<h1>sugkineo</h1>\n<p>Strong n° 4787 <i>Prononciation [soong-kin-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'émouvoir ensemble avec les autres</li>\n<li>jeter dans l'agitation, exciter, remuer, soulever</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κινέω-ῶ</b> <span>[ῑ]</span><br><b>   I <i>tr.</i></b> mouvoir ensemble, <i>càd. :</i><br><b>      1</b> <i>au pass</i>. se mouvoir avec <i>ou</i> en même temps, PLUT. <i>Pyrrh. 16, M. 52</i> b, <i>704</i> d, <i>715</i> d ; <i>avec un dat</i>. LUC. <i>Apol. 5 ;</i><br><b>      2</b> donner du mouvement au style, à l’éloquence, <i>etc</i>. LGN <i>15, 29 ;</i><br><b>      3</b> agiter <i>ou</i> soulever ensemble, POL. <i>15, 17, 1 ;</i> NT. <i>Ap. 6, 12 ;</i><br><b>   II</b> <i>intr. en appar. (s.-e</i>. ἑαυτόν) se mouvoir ensemble, ARSTT. <i>Probl. 27, 11, 2</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκινεω - συγκινέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4788":"<h1>sugkleio</h1>\n<p>Strong n° 4788 <i>Prononciation [soong-kli'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>enfermer ensemble, enclore\n<ol type=\"a\">\n<li>d'un banc de poissons dans un filet</li>\n</ol>\n</li>\n<li>renfermer de tous côtés, fermer complètement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κλείω</b>, <i>anc. att</i>. <b>ξυγ·κλείω</b> <span>(<i>ao</i>. συνέκλεισα, <i>pf</i>. συγκέκλεικα, <i>etc</i>.)</span><br><b>   I</b> enfermer ensemble, <i>d’où :</i><br><b>      1</b> lier étroitement ensemble : πᾶν (σῶμα) ἐν ἄρθροις συγκεκλῃμένον καλῶς, EUR. <i>Bacch. 1301,</i> corps bien joint dans toutes ses articulations, <i>càd</i>. entier, dont il ne manque aucune partie ; σ. τὴν ἀρχὴν τῇ τελευτῇ, ISOCR. <i>238</i> a, rattacher le commencement à la fin ; τῷ προειρημένῳ συγκεκλειμένον, ISOCR. <i>342</i> d, dans le rapport le plus étroit avec ce qui a été dit auparavant ; σ. τὰς ἀσπίδας, XÉN. <i>Cyr. 7, 1, 33,</i> joindre étroitement les boucliers les uns aux <i>autres, càd</i>. former des rangs serrés ; <i>abs</i>. συγκλῄσαντες ἀπεχώρησαν, THC. <i>4, 35,</i> ils se retirèrent en rangs serrés ; τὸ οὐ ξυγκλῃσθέν, THC. <i>5, 72,</i> le vide (dans l’armée) ; σ. τινὰς ἔριδι, EUR. <i>Andr. 122,</i> faire se heurter, mettre aux prises plusieurs personnes ; <i>abs</i>. fermer le passage ; ἡ πολεμία ξυνέκλῃε διὰ μέσου, THC. <i>5, 64,</i> le territoire ennemi fermait la route (par laquelle il fallait passer) ;<br><b>      2</b> fermer, clore : βλέφαρα, XÉN. <i>Mem. 1, 4, 6,</i> les paupières ; ὄμμα, EUR. <i>Ion 241,</i> les yeux ; τοὺς ὀφθαλμούς, DÉM. <i>1259, 13,</i> boucher les yeux à qqn en les frappant, <i>càd</i>. faire que les yeux se ferment par l’enflure ; σ. στόμα, EUR. <i>Hipp. 498,</i> fermer la bouche ; σ. πύλας, THC. <i>4, 67 ;</i> θύρας, XÉN. <i>An. 7, 1, 12,</i> fermer les portes à clef ; <i>abs</i>. ξύγκλειε, AR. <i>Ach. 1096,</i> ferme à clef ; σ. δικαστήρια, AR. <i>Eq. 1317 ;</i> τὸ δεσμωτήριον, AND. <i>7, 26,</i> fermer les tribunaux, la prison ; δίκτυον, ARSTT. <i>H.A. 4, 8,</i> fermer un filet ; <i>fig</i>. ξυγκεκλῃμένη πέπλοις, EUR. <i>Hec. 487,</i> enveloppée de voiles ;<br><b>      3</b> enfermer, ceindre, cerner, <i>acc</i>. HDT. <i>4, 157 ; 7, 41 ;</i> PLUT. <i>Per. 33 ;</i> σ. τὴν ἐκκλησίαν ἐς τὸν Κολωνόν, THC. <i>8, 67,</i> serrer, entasser l’assemblée à Kolônos ; σ. τοὺς πολεμίους ἐντὸς τειχῶν, POL. <i>1, 17, 8,</i> enfermer l’ennemi dans l’enceinte de ses murs ; εἰς πολιορκίαν, POL. <i>1, 8, 2,</i> bloquer l’ennemi pour un siège ; <i>d’où</i> enfermer, emprisonner : θεοὺς τῇ ὕλῃ, PLUT. <i>M. 436</i> b, les dieux dans la matière ; <i>au pass</i>. λίμνη συγκεκληϊμένη πάντοθεν οὔρεσιν, HDT. <i>7, 129,</i> lac enfermé de toutes parts par des montagnes ; <i>fig</i>. réduire à l’étroit, aux extrémités : πρὸς ἔσχατον καιρόν, POL. <i>11, 2, 10,</i> réduire aux dernières extrémités ; εἰς ὅμηρα καὶ φόρους, POL. <i>21, 9, 9 ; 15, 20, 7,</i> à l’obligation de donner des otages et de payer une contribution ; πρὸς ἀργύριον, DS. <i>1, 54,</i> contraindre à un paiement d’argent ; <i>au pass</i>. συγκλείεσθαι ὑπὸ τῶν καιρῶν, POL. <i>2, 60, 4 ;</i> ὑπὸ τῶν πραγμάτων, POL. <i>11, 20, 7,</i> être contraint par les circonstances, par les affaires ; <i>abs</i>. συγκλειούσης τῆς ὥρας, POL. <i>17, 7, 3,</i> comme la saison pressait ; <i>cf</i>. POL. <i>17, 9, 2 ; au pass</i>. εἰς χαλεπὸν συγκεκλεισμένος βίον, MÉN. <i>4, 263 Meineke</i> réduit à une vie difficile ;<br><b>      4</b> former en fermant : θέατρον αὐτῷ συγκλείουσιν, PHILSTR. <i>Im. p. 870,</i> ils forment autour de lui un théâtre.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass</i>. συγκέκλειμαι, ISOCR. <i>342</i> d ; <i>ou</i> συγκέκλεισμαι, MÉN. <i>l. c. ;</i> DS. <i>15, 63. Ion</i>. συγκληΐω, HDT. <i>4, 157 ; 7, 41 ; d’où ao. épq</i>. συνεκλήϊσσα, NONN. <i>D. 48, 309 ; pf. part</i>. συγκεκληϊμένος (<i>v. ci-dessus) ; anc. att</i>. ξυγκλῄω, <i>d’où impf. 3 sg</i>. ξυνέκλῃε, THC. <i>5, 64</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκλειω - συγκλείω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G4789":"<h1>sugkleronomos</h1>\n<p>Strong n° 4789 <i>Prononciation [soong-klay-ron-om'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un cohéritier</li>\n<li>quelqu'un qui obtient quelque chose qui lui est destiné avec les autres, un co-participant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κληρονόμος, ος, ον</b>, cohéritier, NT. <i>Rom. 8, 17 ; Eph. 3, 6, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκληρονομος - συγκληρονόμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4790":"<h1>sugkoinoneo</h1>\n<p>Strong n° 4790 <i>Prononciation [soong-koy-no-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>devenir un participant parmi les autres, ou être associé à une chose</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κοινωνέω-ῶ :<br>      1</b> avoir une part de, participer à : τινος, HPC. <i>Art. 840 ;</i> DÉM. <i>1299, 20,</i> à qqe ch. ; τινί τινος, ALEX. (<i>Com. fr. 3, 456</i>) à qqe ch. avec qqn ;<br><b>      2</b> être compagnon avec, <i>fig</i>. vivre avec : τινι, NT. <i>Apoc. 18, 4 ; Eph. 5, 11</i> avec qqe ch.<br><span><b>Étym</b>. le péché, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκοινωνεω - συγκοινωνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4791":"<h1>sugkoinonos</h1>\n<p>Strong n° 4791 <i>Prononciation [soong-koy-no-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>participant avec les autres dans toute chose, partenaire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κοινωνός, ός, όν</b>, qui participe à, <i>gén</i>. NT. <i>Rom. 11, 17 ; 1Cor. 9, 23 ; avec</i> ἐν <i>et le dat</i>. NT. <i>Apoc. 1, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκοινωνος - συγκοινωνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4792":"<h1>sugkomizo</h1>\n<p>Strong n° 4792 <i>Prononciation [soong-kom-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>transporter ou amener ensemble, rassembler\n<ol type=\"a\">\n<li>engranger des récoltes, mettre dans des greniers</li>\n</ol>\n</li>\n<li>porter avec d'autres, aider à transporter, le mort qui doit être enseveli\n<ol type=\"a\">\n<li>enterrer, ensevelir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κομίζω</b>, <i>anc. att</i>. <b>ξυγ·κομίζω</b> (<i>fut</i>. ίσω ; <i>att</i>. ιῶ, <i>ao</i>. συνεκόμισα ; <i>pf. pass</i>. συγκεκόμισμαι) :<br><b>      1</b> porter <i>ou</i> amener ensemble, XÉN. <i>Ages. 1, 21 ;</i> PLUT. <i>Ages. 19 ; particul</i>. ramasser, recueillir, récolter, HDT. <i>1, 22 ; 2, 121, etc. ;</i> XÉN. <i>Mem. 2, 8, 3, etc. ;</i> DS. <i>4, 82 ; au pass</i>. HDT. <i>8, 25 ;</i><br><b>      2</b> amasser, gagner, SOPH. <i>O.C. 585 ;</i><br><b>      3</b> porter en terre, inhumer, SOPH. <i>Aj. 1048 ;</i> PLUT. <i>Syll. 38</i> ;<br><i><b>Moy</b>. :</i><br><b>      1</b> mener avec soi, XÉN. <i>Cyr. 8, 2, 24 ;</i><br><b>      2</b> récolter, recueillir pour soi, XÉN. <i>An. 6, 6, 37, etc. ; fig</i>. recueillir : εἰς τὴν ψυχήν, XÉN. <i>Cyr. 1, 5, 12,</i> dans son âme ; τῇ μνήμῃ, LUC. <i>Nigr. 10,</i> dans son souvenir.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκομιζω - συγκομίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4793":"<h1>sugkrino</h1>\n<p>Strong n° 4793 <i>Prononciation [soong-kree'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>joindre ensemble convenablement, composer, combiner</li>\n<li>interpréter</li>\n<li>comparer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κρίνω</b> <span>[ῑ <i>prés.,</i> ῐ <i>fut</i>.]</span><br><b>      1</b> assembler, combiner, unir, PLAT. <i>Tim. 67</i> d, <i>etc. ; p. opp. à</i> διακρίνω, EMPÉD. (ARSTT. <i>Metaph. 1, 4, 6</i>) ; T. LOCR. <i>101</i> c ; <i>d’où au pass</i>. être formé par la réunion de plusieurs parties, HPC. <i>1170</i> c ; PLAT. <i>Phæd. 72</i> c, <i>Parm. 157</i> a, <i>etc. ;</i> PLUT. <i>M. 905</i> a ;<br><b>      2</b> rapprocher, comparer, <i>acc</i>. POL. <i>14, 3, 7 ;</i> τι πρός τι, ARSTT. <i>Rhet. 1, 9, 38 ;</i> POL. <i>4, 11, 1, etc. ;</i> τί τινι, ANTH. <i>12, 204,</i> une ch. à une autre ; ἑαυτόν τινι, PLUT. <i>C. Gracch. 4,</i> se comparer à qqn ;<br><b>      3</b> conjecturer, interpréter par conjecture, POL. <i>12, 10, 1 ; particul</i>. interpréter des songes, SPT. <i>Gen. 40, 8 ; Dan. 5, 12 ;</i><br><b>      4</b> juger qqn d’après qqe ch. ANTH. <i>7, 137 ;</i><br><b>      5</b> <i>en gén</i>. déterminer, décider : τί ποιήσωσιν, SPT. <i>Num. 15, 34,</i> ce qu’ils pourront faire ;<br><b><i>Moy.</i></b> se mesurer avec un autre, DS. <i>1, 58 ; 4, 14 ; emploi blâmé par</i> LUC. <i>Sol. 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκρινω - συγκρίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4794":"<h1>sugkupto</h1>\n<p>Strong n° 4794 <i>Prononciation [soong-koop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>plier complètement en avant, être courbé vers le sol, voûté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·κύπτω</b> <span>(<i>ao</i>. συνέκυψα, <i>pf</i>. συγκέκυφα)</span><br><b>   I</b> s’incliner en se repliant sur soi-même : σ. τῷ προσώπῳ, SPT. <i>Job 9, 27,</i> baisser le visage ; <i>particul. :</i><br><b>      1</b> se courber par lassitude, PHILSTR. <i>Im. 2, 20 ;</i> NT. <i>Luc. 13, 11 ;</i><br><b>      2</b> se courber pour observer qqe ch. : περί τινος, SYN. <i>273</i> a, pour étudier qqe ch. ;<br><b>      3</b> <i>t. de tact</i>. opérer un mouvement convergent, XÉN. <i>An. 3, 4, 19 ;</i><br><b>   II</b> s’incliner ensemble, <i>particul</i>. se pencher l’un vers l’autre, AR. <i>Vesp. 570 ; avec</i> πρός <i>et l’acc</i>. ARSTT. <i>H.A. 6, 18, 11 ;</i><br><b>   III</b> se pencher de manière à se toucher, <i>d’où</i> s’aboucher, se concerter pour agir ensemble, HDT. <i>7, 145 ; p. suite, en mauv. part,</i> conspirer, comploter, HDT. <i>3, 82 ; 7, 145 ;</i> AR. <i>Eq. 854</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκυπτω - συγκύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4795":"<h1>sugkuria</h1>\n<p>Strong n° 4795 <i>Prononciation [soong-koo-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>par accident, par chance, par hasard</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγκυρία, ας (ἡ)</b> <span>[κῠ]</span> <i>c</i>. συγκύρησις NT. <i>Luc. 10, 31</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. συγκυρίη, HPC. <i>49, 28, etc</i>.</span>\n<br><br>\n<b>συγκύρησις, εως (ἡ)</b> <span>[κῠ]</span> <i>c</i>. συγκύρημα POL. <i>9, 12, 6 ;</i> DL. <i>10, 98</i>.<br><br>\n<b>συγκύρημα, ατος (τὸ)</b> <span>[κῠ]</span> rencontre fortuite, accident, événement, POL. <i>4, 86, 2 ;</i> DH. <i>9, 38, etc</i>.<br><span><b>Étym</b>. συγκυρέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγκυρια - συγκυρία</font></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4796":"<h1>sugchairo</h1>\n<p>Strong n° 4796 <i>Prononciation [soong-khah'-ee-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se réjouir avec, prendre part à la joie d'un autre</li>\n<li>se réjouir ensemble, se féliciter, se congratuler</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·χαίρω</b> <span>(<i>f</i>. συγχαρήσομαι <span>[ᾰ]</span>, <i>ao.2</i> συνεχάρην <span>[ᾰ]</span>)</span><br><b>      1</b> se réjouir avec : τινί, ARSTT. <i>Nic. 9, 4, 1, etc</i>. avec qqn ; <i>abs</i>. ESCHL. <i>Ag. 793 ;</i> AR. <i>Pax 1317 ;</i> τινί, AR. <i>Eq. 1333 ;</i> PLAT. <i>Epin. 988</i> b ; ἐπί τινι, XÉN. <i>Hier. 11, 12,</i> de qqe ch. ; ὅτι, ESCHN. <i>34, 9,</i> de ce que ;<br><b>      2</b> rendre grâces : τινί τινος, DÉM. <i>194, 23,</i> à qqn de qqe ch. ;<br><b>      3</b> féliciter : τινὶ ἐπί τινι, POL. <i>30, 16, 1,</i> qqn de qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. impér</i>. συγχάρηθι <span>[ᾰ]</span> ANACREONT. <i>31, 30</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγχαιρω - συγχαίρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>Philippiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4797":"<h1>sugcheo</h1>\n<p>Strong n° 4797 <i>Prononciation [soong-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>verser ensemble</li>\n<li>déranger l'esprit de quelqu'un, pousser au tumulte ou à la révolte</li>\n<li>confondre ou égarer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·χέω</b>, verser ensemble, <i>d’où :</i><br><b>      1</b> bouleverser, brouiller, confondre, <i>acc</i>. IL. <i>15, 364 ;</i> ἡνία δέ σφιν σύγχυτο, IL. <i>16, 471,</i> les rênes s’étaient embrouillées, enchevêtrées ; σ. τὰ διακεκριμένα, PLAT. <i>Phil. 46</i> e, brouiller <i>ou</i> confondre ce qui a été trié ; οὐ κεχωρισμένον (<i>ou</i> διωρισμένον), ἀλλὰ συγκεχυμένον, PLAT. <i>Rsp. 524</i> b <i>et c,</i> non séparé <i>ou</i> trié, mais confondu ; σ. τὰ γράμματα, EUR. <i>I.A. 37,</i> effacer les lettres ; σ. τὰς ψήφους, IS. <i>52, 26,</i> mélanger les cailloux servant au vote ; τὰς τάξεις, POL. <i>1, 40, 13,</i> mettre le désordre dans les rangs ; <i>fig</i>. συνεχέοντο αἱ γνῶμαι τῶν φαμένων, HDT. <i>7, 142,</i> les vues de ceux qui disaient…, étaient confuses, se contredisaient ; σ. θυμόν, IL. <i>9, 612 ; 13, 808, etc</i>. troubler l’esprit <i>ou</i> le courage de qqn, le rendre hésitant, indécis ; <i>avec un rég. de pers. :</i> σ. τινα, OD. <i>8, 139 ;</i> HDT. <i>8, 99,</i> troubler qqn ; <i>au pass</i>. EUR. <i>Med. 1005 ;</i><br><b>      2</b> bouleverser, renverser, ruiner (une maison, une construction, <i>etc</i>.) HDT. <i>4, 127 ;</i> EUR. <i>Hipp. 813, etc. ; au plur</i>. LUC. <i>Cal. 1 ;</i> σ. ἄστυ, PLUT. <i>M. 557</i> b, convertir une ville en un monceau de décombres ; σ. ὁδόν, HDT. <i>7, 115,</i> rendre une route impraticable, <i>etc. ; fig</i>. σ. ὅρκια, IL. <i>4, 269 ;</i> ὅρκους, EUR. <i>Hipp. 1063, etc</i>. violer des serments ; τὰ νόμιμα, HDT. <i>7, 136 ;</i> τὸν νόμον, DÉM. <i>640, 2,</i> bouleverser, <i>càd</i>. violer les lois, la loi ; τὴν πολιτείαν, DÉM. <i>729, 4,</i> bouleverser le gouvernement : συγχεῖ πάνθ' ὁ χρόνος, SOPH. <i>O.C. 609,</i> le temps bouleverse tout ; ἄνω κάτω τὰ πάντα σ. ὁμοῦ, EUR. <i>Bacch. 349,</i> bouleverser tout de fond en comble ; λέλυται πάντα, συγκέχυται, DÉM. <i>777, 9,</i> tout est relâché, bouleversé ;<br><b>      3</b> rendre vain, faire échouer (le travail, les efforts, <i>etc</i>.) IL. <i>15, 366, 473, etc. ;</i><br><b>      4</b> exposer sans ordre, d’une façon confuse, <i>en parl. de l’orateur, acc</i>. HERMOG. (<i>W. 3, 211, 13 ; 218, 11</i>) ; <i>au pass</i>. HERMOG. (<i>W. 3, 215, 22</i>) ;<br><b>      5</b> provoquer en faisant de l’agitation, <i>d’où</i> exciter : πόλεμον, POL. <i>4, 10, 3, etc</i>. une guerre.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. pass. réc</i>. συγχεθήσομαι <i>p</i>. συγχυθήσομαι, CLÉM. <i>2, 293 Migne ; ao.2 moy. 3 sg. poét</i>. σύγχυτο.<br><span><b>Étym</b>. <i>v. ci-dessus</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγχεω - συγχέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G4798":"<h1>sugchraomai</h1>\n<p>Strong n° 4798 <i>Prononciation [soong-khrah'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>utiliser avec n'importe qui, utiliser conjointement</li>\n<li>s'associer avec, avoir des relations avec</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>συγ·χράομαι-ῶμαι :<br>   I</b> user de qqe ch. d’accord avec son propre intérêt, <i>d’où</i> profiter de, <i>dat</i>. POL. <i>1, 8, 1 ; 3, 14, 5 ; 4, 6, 2 ; 18, 34, 6, etc. ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> emprunter : παρά τινός τι, POL. <i>1, 20, 14,</i> qqe ch. à qqn ;<br><b>      2</b> avoir des relations de commerce avec, <i>dat</i>. M. RUBR. <i>31 ;</i><br><b>      3</b> avoir commerce <i>ou</i> s’associer avec, <i>dat</i>. NT. <i>Joh. 4, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγχραομαι - συγχράομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G4799":"<h1>sugchusis</h1>\n<p>Strong n° 4799 <i>Prononciation [soong'-khoo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>confusion, dérangement, agitation, remue-ménage\n<ol type=\"a\">\n<li>de personnes déréglées</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σύγχυσις, εως (ἡ)</b> <span>[χῠ]</span><br><b>      1</b> confusion, mélange, HPC. <i>1174</i> f ; POL. <i>30, 13, 7 ;</i> CIC. <i>Att. 6, 9, 1 ;</i> PLUT. <i>M. 122</i> b, <i>990</i> a ; <i>particul</i>. confusion politique, POL. <i>7, 8, 4 ;</i><br><b>      2</b> bouleversement, ruine, EUR. <i>Andr. 292, 959 ;</i> violation de lois, de traités, de serments, THC. <i>1, 146 ; 5, 46 ;</i> ISOCR. <i>64</i> c ; PLAT. <i>Rsp. 379</i> e ; PLUT. <i>Alc. 14 ;</i><br><b>      3</b> trouble de l’esprit, confusion, stupeur, EUR. <i>I.A. 354, 1128 ;</i> LUC. <i>Nigr. 35, etc</i>.<br><span><b>Étym</b>. συγχέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">συγχυσις - σύγχυσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>"};
